:root { color-scheme: dark; --bg: #0f1318; --panel: #151a21; --line: #26303b; --text: #dde6ee; --dim: #8fa0b1; --accent: #ffd24a; }
* { box-sizing: border-box; }
html, body, #app { height: 100%; margin: 0; }
body { background: var(--bg); color: var(--text); font: 14px system-ui, sans-serif; overflow: hidden; }
.app { display: flex; flex-direction: column; height: 100%; }
.bar { display: flex; align-items: center; gap: 6px; padding: 6px 10px; background: var(--panel); border-bottom: 1px solid var(--line); flex-wrap: wrap; }
.bar .brand { margin-right: 8px; letter-spacing: .04em; }
.bar .grow { flex: 1; }
.bar .sep { width: 1px; height: 20px; background: var(--line); margin: 0 4px; }
.bar .fps { color: var(--dim); font-variant-numeric: tabular-nums; min-width: 52px; text-align: right; }
button { font: inherit; color: var(--text); background: #1d2530; border: 1px solid var(--line); border-radius: 6px; padding: 5px 11px; cursor: pointer; }
button:hover:not(:disabled) { background: #263140; }
button:disabled { opacity: .4; cursor: default; }
button.on { background: var(--accent); color: #1a1500; border-color: var(--accent); }
.seg { display: inline-flex; gap: 0; }
.seg button { border-radius: 0; }
.seg button:first-child { border-radius: 6px 0 0 6px; }
.seg button:last-child { border-radius: 0 6px 6px 0; }
.body { flex: 1; min-height: 0; display: flex; }
.view { flex: 1; min-width: 0; position: relative; touch-action: none; }
.view canvas { display: block; }
.panel { width: 300px; background: var(--panel); overflow: auto; padding: 8px 12px 24px; }
.panel.left { width: 190px; border-right: 1px solid var(--line); }
.panel.right { border-left: 1px solid var(--line); }
.panel h3 { margin: 6px 0 8px; font-size: 13px; color: var(--dim); }
.panel h3.sub { margin-top: 18px; }
.list { list-style: none; margin: 0; padding: 0; display: grid; gap: 4px; }
.list button { width: 100%; text-align: left; }
.hint { color: var(--dim); font-size: 12px; line-height: 1.4; }
@media (max-width: 760px) {
  .body { flex-direction: column; }
  .view { flex: 0 0 52%; }
  .panel, .panel.left { width: auto; flex: 1; border: 0; border-top: 1px solid var(--line); }
  .panel.left { display: none; }
  /* the maker keeps its tool strip on phones: a short scrollable band between the view and the settings */
  .maker .view { flex: 0 0 46%; order: 1; }
  .maker .panel.left { display: block; order: 2; flex: 0 0 auto; width: auto; padding: 4px 6px; border-top: 1px solid var(--line); }
  .maker .panel.left .hint { display: none; }
  .maker .panel.left [data-kit="toolbar"] { flex-direction: row !important; overflow-x: auto; border: 0 !important; padding: 2px !important; gap: 6px !important; }
  .maker .panel.left [data-kit="toolbar"] > div { flex-wrap: nowrap !important; flex: 0 0 auto; }
  .maker .panel.right { order: 3; }
}

.race { position: relative; width: 100%; height: 100%; }
.race .view { position: absolute; inset: 0; }
.race .mini { position: absolute; right: 12px; top: 12px; }
.race-hint { position: absolute; left: 50%; bottom: 10px; transform: translateX(-50%); color: #ffffffaa; font-size: 12px; pointer-events: none; text-shadow: 0 1px 3px #000; }
.to-editor { position: absolute; left: 12px; bottom: 12px; color: #fff; background: #0008; padding: 4px 10px; border-radius: 6px; text-decoration: none; font-size: 12px; }
.results { position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); background: #101820ee; border: 1px solid #2c3b4a; border-radius: 12px; padding: 18px 26px; min-width: 300px; }
.results h2 { margin: 0 0 10px; }
.results ol { list-style: none; padding: 0; margin: 0 0 12px; display: grid; gap: 4px; }
.results li { display: grid; grid-template-columns: 48px 1fr 80px; gap: 8px; padding: 4px 6px; border-radius: 6px; }
.results li.me { background: #ffd24a22; color: #ffd24a; }

.maker { display: flex; flex-direction: column; height: 100%; position: relative; }
.maker .hist { color: var(--dim); font-size: 12px; padding: 0 6px; }
.maker .go { background: #2f8f5b; border-color: #2f8f5b; font-weight: 600; }
.maker .status { margin: 4px 0 8px; padding: 8px 10px; border-radius: 8px; background: #1b2530; font-size: 13px; line-height: 1.35; }
.maker .status[data-valid="true"] { background: #17382a; color: #8dffbe; }
.maker .btns { display: flex; flex-wrap: wrap; gap: 6px; margin: 6px 0; }
.maker .row { display: grid; grid-template-columns: auto 1fr auto; gap: 8px; align-items: center; font-size: 13px; color: var(--dim); }
.maker .panel.left { width: 230px; }
.toasts { position: absolute; left: 50%; bottom: 22px; transform: translateX(-50%); display: grid; gap: 6px; justify-items: center; pointer-events: none; }
.toast { background: #101820ee; border: 1px solid #2c3b4a; color: #e8f0f7; padding: 7px 14px; border-radius: 999px; font-size: 13px; animation: toast-in .18s ease-out; }
.toast.ok { border-color: #2f8f5b; color: #9bf0c0; }
.toast.warn { border-color: #b8860b; color: #ffd98a; }
.toast.error { border-color: #b8433b; color: #ffb3a8; }

.looks { display: flex; gap: 6px; padding: 6px 10px; background: var(--panel); border-bottom: 1px solid var(--line); overflow-x: auto; align-items: center; }
.looks button { white-space: nowrap; padding: 4px 10px; font-size: 12px; }
.looks .hour { margin-left: auto; display: flex; gap: 8px; align-items: center; color: var(--dim); font-size: 12px; min-width: 220px; }
.looks .hour input { flex: 1; }
@keyframes toast-in { from { transform: translateY(8px) scale(.96); opacity: 0; } to { transform: none; opacity: 1; } }

/* ---- drivers (modulators) panel ---- */
.maker .drivers { margin: 4px 0 12px; padding-bottom: 6px; border-bottom: 1px solid var(--line, #2c3a44); }
.maker .driver { background: rgba(255,255,255,0.04); border-radius: 8px; padding: 6px 8px; margin: 6px 0; }
.maker .driver.off { opacity: 0.5; }
.maker .driver-head { display: flex; align-items: center; gap: 6px; }
.maker .driver-head b { flex: 1; font-size: 13px; }
.maker .driver-head button { padding: 2px 8px; }
.maker .driver .bad { color: #ff9a5e; font-size: 12px; }
.maker .driver-edit { margin-top: 6px; }
.maker .driver-add .chips { display: flex; flex-wrap: wrap; gap: 6px; margin: 8px 0; max-height: 220px; overflow: auto; }
.maker .chip { display: inline-flex; align-items: center; gap: 6px; padding: 4px 8px; font-size: 12px; }
.maker .chip svg { stroke: currentColor; }
.maker .panel.right { overflow-x: hidden; }
.maker .driver-edit svg, .maker .driver-edit canvas { max-width: 100%; height: auto; }
.maker .driver-edit input, .maker .driver-edit select { max-width: 100%; box-sizing: border-box; }

.race .mute { position: absolute; right: 12px; bottom: 12px; background: #0008; color: #fff; border: 0; border-radius: 6px; padding: 4px 10px; font-size: 16px; cursor: pointer; }

/* ---- sounds panel ---- */
.maker .sound-list { list-style: none; margin: 8px 0 0; padding: 0; }
.maker .sound-list li { border-bottom: 1px solid var(--line, #26303b); padding: 4px 0; }
.maker .sound-row { display: flex; align-items: center; gap: 8px; }
.maker .sound-row .grow { flex: 1; text-transform: capitalize; }
.maker .sound-row i { color: var(--accent, #ffd24a); font-style: normal; }
.maker .sound-edit { padding: 6px 0 8px; }
.maker .sound-list li.edited .grow { color: var(--accent, #ffd24a); }

.maker .saved { color: var(--ok, #5fd38d); font-size: 12px; margin-left: 8px; opacity: 0.85; }

/* ---- help overlay ---- */
.help { position: fixed; inset: 0; z-index: 50; background: rgba(5, 10, 14, 0.62); backdrop-filter: blur(3px); display: grid; place-items: center; padding: 16px; }
.help-card { background: #151a21; border: 1px solid #26303b; border-radius: 14px; padding: 18px 22px; max-width: 560px; width: 100%; max-height: 90vh; overflow: auto; box-shadow: 0 20px 60px rgba(0,0,0,0.5); }
.help-card h2 { margin: 0 0 8px; }
.help-card table { border-collapse: collapse; margin: 10px 0; width: 100%; }
.help-card th { text-align: left; padding: 3px 12px 3px 0; white-space: nowrap; font-weight: 500; }
.help-card td { padding: 3px 0; color: #c7d3de; }
.help-card kbd { background: #26303b; border-radius: 5px; padding: 1px 7px; font-family: inherit; font-size: 12px; border-bottom: 2px solid #0008; }

.maker .confirm { display: inline-flex; gap: 6px; align-items: center; font-size: 12px; }
.maker .danger { background: #6b2a24; border-color: #ff6b5e; }

.maker .view { position: relative; }
.maker .viewmode { position: absolute; left: 10px; bottom: 10px; z-index: 5; background: #0009; color: #fff; border: 1px solid #ffffff44; border-radius: 999px; padding: 8px 14px; font-size: 13px; min-height: 40px; }
.maker .viewmode.on { background: #ffd24a; color: #111; border-color: #ffd24a; }

.help-card textarea.code { width: 100%; box-sizing: border-box; background: #0f1318; color: #c7d3de; border: 1px solid #26303b; border-radius: 8px; padding: 8px; font: 12px/1.35 ui-monospace, Consolas, monospace; margin: 6px 0; resize: vertical; }
.help-card .bad { color: #ff9a5e; font-size: 13px; }

/* ---- sound lab ---- */
.maker .lab { margin: 6px 0; }
.maker .lab .wave { width: 100%; height: 64px; color: var(--accent, #ffd24a); background: #0f1318; border-radius: 8px; display: block; margin: 6px 0; }
.maker .lab .layer { background: rgba(255,255,255,0.04); border-radius: 8px; padding: 6px 8px; margin: 6px 0; }
.maker .lab .layer-head { display: flex; align-items: center; gap: 6px; }
.maker .lab .layer-head b { flex: 1; }
.maker .lab textarea.code { width: 100%; box-sizing: border-box; background: #0f1318; color: #c7d3de; border: 1px solid #26303b; border-radius: 8px; padding: 6px; font: 11px/1.35 ui-monospace, Consolas, monospace; }
.maker .lab ul.bad { color: #ff9a5e; font-size: 12px; padding-left: 18px; }

.race .pause-btn { position: absolute; left: 50%; top: 10px; transform: translateX(-50%); background: #0008; color: #fff; border: 0; border-radius: 999px; width: 40px; height: 40px; font-size: 18px; cursor: pointer; z-index: 3; }

/* phones: the HUD wraps over two rows, so the minimap and the pause button sit below it on the right */
@media (max-width: 520px) {
  .race .mini { top: 92px; right: 10px; }
  .race .pause-btn { left: auto; right: 10px; top: 200px; transform: none; }
}

.maker .hud-preview { position: relative; background: #0f1a22; border: 1px solid var(--line, #26303b); border-radius: 6px; margin: 6px 0; overflow: hidden; }
.maker .hud-row { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; padding: 4px 0; border-bottom: 1px solid var(--line, #26303b); font-size: 12px; }
.maker .hud-row input[type=number] { width: 54px; }

/* focus mode: inside one thing, the world around it whited out */
.focus-bar { position: absolute; top: 10px; left: 50%; transform: translateX(-50%); z-index: 5; display: flex; gap: 8px; align-items: center; padding: 6px 10px; background: var(--panel); border: 1px solid var(--line); border-radius: 12px; box-shadow: 0 4px 18px rgba(0,0,0,.25); }
.blur-ring { z-index: 4; }

.rig-name { position: absolute; top: 14px; left: 50%; transform: translateX(-50%); z-index: 6; padding: 4px 12px; border-radius: 999px; background: rgba(0,0,0,.55); color: #fff; font-weight: 700; pointer-events: none; }

.sculpt-bar { position: absolute; bottom: 14px; left: 50%; transform: translateX(-50%); z-index: 5; display: flex; gap: 8px; align-items: center; flex-wrap: wrap; justify-content: center; max-width: 92%; padding: 6px 10px; background: var(--panel); border: 1px solid var(--line); border-radius: 12px; box-shadow: 0 4px 18px rgba(0,0,0,.25); }
.sculpt-bar .swatches { display: flex; gap: 3px; flex-wrap: wrap; }
.sculpt-bar .swatches button.on { outline: 3px solid var(--accent2, #f0a); }

/* TASK-24: the checkpoints under Settings (shown with ?checkpoint or ?e2e) */
.checkpoint-list .checkpoint-buttons { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 6px; }
.checkpoint-list .checkpoint-buttons button { min-width: 9.5rem; }

