/*
 * THE interface: a clean warm-white studio. Hairline 1px rules, square corners, no shadows or glows, small tracked capitals for labels,
 * one terracotta accent. Adopted from the "Nested Preset Studio" design. Loaded after shell.css, so it wins by order.
 * Colours are variables that the `interface` preset can override (themeOf writes them inline on the app root).
 */
:root {
  color-scheme: light;
  font-family: Inter, 'Helvetica Neue', Helvetica, Arial, sans-serif;
  --bg: #f4f3ee; --paper: #f8f7f2; --panel: #fbfaf6; --line: #dcdad2; --text: #242722; --dim: #85847b; --faint: #aaa99f;
  --accent: #c56443; --green: #527f6a; --ok: #527f6a; --danger: #b3402e; --gold: #d5a24a;
  --hm-bg: #fbfaf6; --hm-inset: #f1f0ea;
}
body { background: var(--paper); color: var(--text); font: 13px/1.4 Inter, 'Helvetica Neue', Helvetica, Arial, sans-serif; -webkit-font-smoothing: antialiased; }
::selection { background: #d9d9bc; color: #20231f; }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

/* controls */
button { font: 500 12px/1 Inter, sans-serif; color: var(--text); background: transparent; border: 1px solid var(--line); border-radius: 0; padding: 7px 11px; letter-spacing: .02em; transition: background .12s, border-color .12s, color .12s; }
button:hover:not(:disabled) { background: #efeee7; border-color: #c9c7bc; }
button.on { background: var(--text); color: var(--paper); border-color: var(--text); }
button.go, .maker .go { background: var(--accent); border-color: var(--accent); color: #fff; font-weight: 600; }
button.go:hover:not(:disabled) { background: #b25636; border-color: #b25636; }
button.danger, .maker .danger { background: transparent; color: var(--danger); border-color: var(--danger); }
input, select, textarea { font: inherit; color: var(--text); background: #fff; border: 1px solid var(--line); border-radius: 0; padding: 5px 8px; }
input[type=range] { padding: 0; accent-color: var(--accent); background: transparent; border: 0; }
input[type=checkbox] { accent-color: var(--accent); }
.hint { color: var(--dim); font-size: 11px; }
kbd { border-radius: 0; }

/* top bar */
.maker .bar { background: var(--panel); border-bottom: 1px solid var(--line); padding: 0 14px; gap: 8px; min-height: 54px; }
.maker .brand { display: flex; flex-direction: column; gap: 3px; line-height: 1; margin-right: 6px; padding-right: 14px; border-right: 1px solid var(--line); }
.maker .brand b { font-family: var(--font-setmix); font-size: 16px; font-weight: 700; }
.maker .brand i { font-style: normal; font-size: 12px; font-weight: 600; color: var(--dim); }
.maker .crumbs { display: flex; align-items: center; gap: 7px; color: var(--dim); font-size: 11px; min-width: 0; white-space: nowrap; overflow: hidden; }
.maker .crumbs b { color: var(--text); font-weight: 600; }
.maker .crumbs button { padding: 2px 4px; border: 0; color: var(--dim); }
.maker .tabs { display: flex; gap: 0; border: 1px solid var(--line); }
.maker .tabs button { border: 0; border-right: 1px solid var(--line); padding: 7px 12px; font-size: 11px; }
.maker .tabs button:last-child { border-right: 0; }
.maker .hist, .maker .saved { font-size: 12px; color: var(--dim); }
.maker .saved { color: var(--green); }
.maker .looks { background: var(--paper); border-bottom: 1px solid var(--line); padding: 4px 14px; gap: 0; }
.maker .looks button { border: 0; border-right: 1px solid var(--line); padding: 5px 10px; font-size: 12px; color: var(--dim); }
.maker .looks button.on { background: transparent; color: var(--accent); box-shadow: inset 0 -2px 0 var(--accent); }

/* left rail: icons only, labels on hover */
.maker .rail { display: flex; flex-direction: column; align-items: center; gap: 2px; width: 46px; padding: 8px 0; background: var(--panel); border-right: 1px solid var(--line); flex: 0 0 46px; }
.maker .rail button { position: relative; display: grid; place-items: center; width: 34px; height: 34px; padding: 0; border: 0; color: #5d5e55; }
.maker .rail button.on { background: var(--text); color: var(--paper); }
.maker .rail button:hover::after { content: attr(data-label); position: absolute; left: 40px; top: 50%; transform: translateY(-50%); z-index: 40; white-space: nowrap; padding: 4px 8px; background: var(--text); color: var(--paper); font-size: 12px; pointer-events: none; }
.maker .rail .gap { flex: 1; }
.maker .rail hr { width: 22px; border: 0; border-top: 1px solid var(--line); margin: 6px 0; }
.maker .slideout { position: absolute; left: 56px; top: 12px; z-index: 12; width: 190px; background: var(--panel); border: 1px solid var(--line); }
.maker .slideout h4 { margin: 0; padding: 9px 10px; font-size: 12px; color: var(--dim); border-bottom: 1px solid var(--line); }
.maker .slideout .grid { display: grid; grid-template-columns: 1fr 1fr; }
.maker .slideout .grid button { display: flex; align-items: center; gap: 7px; border: 0; border-bottom: 1px solid var(--line); border-right: 1px solid var(--line); padding: 8px; font-size: 11px; text-align: left; }
.maker .slideout .grid button:nth-child(2n) { border-right: 0; }

/* panels */
.panel, .maker .panel { background: var(--panel); color: var(--text); }
.panel.right, .maker .panel.right { width: 320px; border-left: 1px solid var(--line); padding: 0 0 24px; }
.panel.right > * { margin-left: 14px; margin-right: 14px; }
.panel h3, .maker h3 { margin: 16px 14px 8px; font-size: 12px; font-weight: 700; color: var(--dim); padding-bottom: 6px; border-bottom: 1px solid var(--line); }
.maker .panel h3.sub { margin-top: 18px; }
.maker section.rules, .maker .drivers { margin: 4px 14px 12px; border: 0; }
.maker .sound-list li { border-bottom: 1px solid var(--line); }
.maker .status { background: #f1f0ea; border: 1px solid var(--line); border-radius: 0; color: var(--text); }
.maker .status[data-valid="true"] { background: #eef3ef; color: var(--green); border-color: #c9d9cf; }
.maker .btns { gap: 4px; }
.maker .chip, .chip { border-radius: 0; }

/* the preset tree (nested presets) */
.maker .tree { border-bottom: 1px solid var(--line); padding-bottom: 6px; margin: 0; }
.maker .tree h3 { margin-top: 12px; }
.maker .tree ul { list-style: none; margin: 0; padding: 0 0 0 0; }
.maker .tree li ul { padding-left: 14px; border-left: 1px solid var(--line); margin-left: 10px; }
.maker .tree .row { display: flex; align-items: center; gap: 6px; width: 100%; padding: 5px 14px; border: 0; text-align: left; font-size: 12px; color: #4a4b44; }
.maker .tree .row.sel { background: #ecebe4; color: var(--text); font-weight: 600; }
.maker .tree .row small { margin-left: auto; font-size: 12px; color: var(--faint); }
.maker .tree .row svg { color: #8c8a80; flex: 0 0 auto; }

/* focus mode bars */
.focus-bar, .sculpt-bar { background: var(--panel); border: 1px solid var(--line); border-radius: 0; box-shadow: none; }
.focus-bar span { font-size: 12px; color: var(--dim); }
.focus-bar b { color: var(--text); letter-spacing: .04em; }
.sculpt-bar .swatches button { border-radius: 0; }
.sculpt-bar .swatches button.on { outline: 2px solid var(--text); outline-offset: 1px; }
.toast { background: var(--text); color: var(--paper); border: 0; border-radius: 0; font-size: 12px; }
.toast.ok, .toast.warn, .toast.error { color: var(--paper); }
.rig-name { background: var(--text); color: var(--paper); border-radius: 0; font-size: 11px; font-weight: 600; }
.help-card { background: var(--panel); border: 1px solid var(--line); border-radius: 0; color: var(--text); }
.help-card td, .help-card .bad { color: #4a4b44; }
.help-card kbd { background: #ecebe4; border-bottom: 1px solid var(--line); color: var(--text); }
.help-card textarea.code, .maker .lab textarea.code { background: #fff; color: var(--text); border-color: var(--line); border-radius: 0; }
.maker .lab .wave, .maker .hud-preview { background: #fff; border-radius: 0; }

/* race overlays */
.results { background: var(--panel); color: var(--text); border: 1px solid var(--line); border-radius: 0; }
.results li { border-radius: 0; }
.results li.me { background: #ecebe4; color: var(--accent); }
.race .pause-btn, .race .mute, .to-editor { background: rgba(36,39,34,.78); border-radius: 0; }

/* game screens: the clean wall, the hero model, hairline cards */
.hms { color: var(--text); font-family: Inter, sans-serif; }
.hms.hms-bg { background: linear-gradient(90deg, rgba(248,247,242,.98) 0%, rgba(248,247,242,.92) 30%, rgba(248,247,242,0) 62%), url('images/orbit-workspace.webp') center / cover no-repeat, var(--paper); }
.hms.hms-dim { background: rgba(248,247,242,.9); backdrop-filter: blur(4px); }
.hms .hms-logo { background: none; -webkit-background-clip: initial; background-clip: initial; color: var(--text); filter: none; font-weight: 700; letter-spacing: .16em; font-size: clamp(26px, 6vw, 54px); }
.hms .hms-btn { min-height: 46px; font-size: 12px; font-weight: 600; color: var(--text); background: var(--panel); border: 1px solid var(--text); border-radius: 0; box-shadow: none; }
.hms .hms-btn:hover { background: var(--text); color: var(--paper); transform: none; }
.hms .hms-btn.go { background: var(--accent); border-color: var(--accent); color: #fff; box-shadow: none; }
.hms .hms-btn.go:hover { background: #b25636; border-color: #b25636; color: #fff; }
.hms .hms-btn.quiet { background: transparent; border-color: var(--line); }
.hms .hms-panel { background: var(--panel); border: 1px solid var(--line); border-radius: 0; box-shadow: none; }
.hms .hms-card { background: var(--panel); color: var(--text); border: 1px solid var(--line); border-radius: 0; box-shadow: none; }
.hms .hms-card:hover { background: #f1f0ea; }
.hms .hms-card[aria-pressed="true"] { border-color: var(--accent); background: var(--panel); transform: none; box-shadow: inset 0 0 0 1px var(--accent); }
.hms .hms-seg { border-radius: 0; }
.hms .hms-seg button { color: var(--text); border-radius: 0; }
.hms .hms-seg button[aria-pressed="true"] { background: var(--text); color: var(--paper); }
.hms .hms-bar i, .hms .hms-meter, .hms .hms-progress { background: #ecebe4; border-color: var(--line); border-radius: 0; }
.hms .hms-bar i b, .hms .hms-meter b, .hms .hms-progress b { background: var(--accent); border-radius: 0; }
.hms .hms-pod .blk { background: #e4e2d8; color: var(--text); border-radius: 0; border: 1px solid var(--line); }
.hms .hms-pod [data-podium="1"] .blk { background: var(--gold); color: var(--text); }
.hms tr[data-me="true"] td { background: #ecebe4; }
.hms, .hms td, .hms th { color: var(--text); }

/* square corners everywhere (the kit and the HUD set their own radii inline) */
.maker *, .hms *, .game-app *, .race * { border-radius: 0 !important; }
.race .mini canvas, .race .mini svg { border-radius: 0 !important; }

.hms.hms-bg { align-items: flex-start; padding-left: clamp(20px, 8vw, 120px); text-align: left; }
.hms.hms-bg > * { align-self: flex-start; }
.hms.hms-bg > * { max-width: min(40vw, 460px); }
.hms.hms-bg .hms-logo { font-size: clamp(22px, 3.6vw, 44px); }

.island-hint { position: absolute; left: 50%; bottom: 14px; transform: translateX(-50%); margin: 0; padding: 5px 12px; background: rgba(36,39,34,.72); color: #f8f7f2; font-size: 12px; pointer-events: none; }
.island-menu { position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); width: 260px; display: grid; gap: 6px; padding: 16px; background: var(--panel); border: 1px solid var(--line); }
.island-menu { width: 288px; gap: 4px; }
.island-menu .im-group { display: grid; gap: 4px; margin-top: 12px; }
.island-menu h3 { margin: 0 0 6px; font-size: 14px; font-weight: 600; color: var(--text); }
.island-menu .im-group h4 { margin: 0 0 2px; font-size: 12px; font-weight: 600; color: var(--dim); }
.island-menu button { padding: 10px; }

/* the shell: main menu, hub, activities, activity menus */
.shell { position: absolute; inset: 0; overflow: hidden; background: #06070b; color: var(--text); }
.shell-layer { position: absolute; inset: 0; }
.shell-ui { pointer-events: none; }
.shell-ui > * { pointer-events: auto; }
.shell-brand { position: absolute; left: clamp(20px, 6vw, 90px); top: clamp(24px, 8vh, 80px); display: flex; flex-direction: column; gap: 6px; color: #f4f3ee; }
.shell-brand b { font-size: clamp(30px, 5vw, 58px); font-weight: 700; letter-spacing: .2em; line-height: 1; }
.shell-brand i { font-style: normal; font-size: 10px; font-weight: 600; letter-spacing: .3em; color: #b9b7ab; }
.shell-brand.small { position: static; }
.shell-brand.small b { font-size: 13px; letter-spacing: .16em; color: var(--text); }
.shell-brand.small i { font-size: 12px; color: var(--dim); }
.shell-menu { position: absolute; left: clamp(20px, 6vw, 90px); bottom: clamp(40px, 12vh, 120px); display: grid; gap: 0; width: min(260px, 70vw); border: 1px solid rgba(244,243,238,.35); background: rgba(6,7,11,.55); backdrop-filter: blur(6px); }
.shell-menu button { padding: 15px 18px; text-align: left; font-size: 12px; font-weight: 600; color: #f4f3ee; border: 0; border-bottom: 1px solid rgba(244,243,238,.2); background: transparent; }
.shell-menu button:last-child { border-bottom: 0; }
.shell-menu button:hover { background: #f4f3ee; color: #06070b; }
.shell-menu button.go { background: var(--accent); color: #fff; }
.shell-foot { position: absolute; left: clamp(20px, 6vw, 90px); bottom: 16px; margin: 0; font-size: 12px; color: #8e8d84; }
.shell-top { position: absolute; left: 0; right: 0; top: 0; display: flex; align-items: center; gap: 14px; padding: 0 16px; height: 54px; background: var(--panel); border-bottom: 1px solid var(--line); }
.shell-top .grow { flex: 1; }
.shell-credits { font-size: 11px; font-weight: 600; letter-spacing: .1em; color: var(--accent); }
.shell-card { position: absolute; right: 24px; top: 78px; width: 300px; padding: 16px; background: var(--panel); border: 1px solid var(--line); color: var(--text); }
.shell-card h3 { margin: 0 0 6px; font-size: 16px; }
.shell-window { position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); width: min(780px, 92vw); max-height: 86vh; overflow: auto; padding: 0 0 16px; background: var(--panel); border: 1px solid var(--line); color: var(--text); }
.shell-window.narrow { width: min(460px, 92vw); }
.shell-window.wide { top: 78px; transform: translateX(-50%); }
.shell-window > header { display: flex; align-items: center; gap: 12px; padding: 10px 16px; border-bottom: 1px solid var(--line); }
.shell-window > header h3 { margin: 0; flex: 1; font-size: 12px; color: var(--dim); border: 0; padding: 0; }
.shell-window > .row, .shell-window > p, .shell-window > .btns { margin: 12px 16px 0; }
.shell-cards { display: grid; grid-template-columns: repeat(auto-fill, minmax(210px, 1fr)); gap: 0; margin: 12px 16px 0; border-top: 1px solid var(--line); border-left: 1px solid var(--line); }
.shell-activity { display: flex; flex-direction: column; gap: 6px; padding: 14px; border: 0; border-right: 1px solid var(--line); border-bottom: 1px solid var(--line); background: transparent; text-align: left; align-items: flex-start; }
.shell-activity h4 { margin: 0; font-size: 14px; }
.shell-activity p { margin: 0; font-size: 12px; color: #5d5e55; }
.shell-activity .thumb { width: 100%; height: 108px; display: grid; place-items: center; background: var(--hm-inset); border: 1px solid var(--line); }
.shell-activity .thumb > span { width: 100%; height: 100%; }
.shell-activity.new { align-items: center; justify-content: center; color: var(--dim); min-height: 120px; }
.shell-racing { position: absolute; inset: 0; display: flex; background: var(--paper); }
.shell-racing-nav { display: flex; flex-direction: column; gap: 14px; width: 250px; padding: 22px 0 18px; background: var(--panel); border-right: 1px solid var(--line); }
.shell-racing-nav > .shell-brand, .shell-racing-nav > .shell-credits, .shell-racing-nav > button { margin: 0 18px; }
.shell-racing-nav nav { display: flex; flex-direction: column; }
.shell-racing-nav nav button { display: flex; align-items: center; gap: 10px; border: 0; border-left: 2px solid transparent; padding: 11px 18px; text-align: left; font-size: 12px; }
.shell-racing-nav nav button.on { background: #ecebe4; border-left-color: var(--accent); color: var(--text); }
.shell-racing-nav .grow { flex: 1; }
.shell-racing-main { flex: 1; padding: clamp(24px, 5vw, 64px); max-width: 780px; overflow: auto; }
.shell-racing-main h2 { margin: 0 0 10px; font-size: 24px; font-weight: 600; letter-spacing: .02em; }
.shell-racing-main p { max-width: 560px; color: #4a4b44; }
.shell-list { list-style: none; margin: 12px 0; padding: 0; border-top: 1px solid var(--line); max-width: 560px; }
.shell-list li { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 10px 2px; border-bottom: 1px solid var(--line); font-size: 13px; }
.shell-list.rank li { display: grid; grid-template-columns: 34px 1fr auto; }
.shell-list.rank li.me { background: #ecebe4; font-weight: 700; }

/* build mode in the world: crosshair, hotbar, inventory */
.crosshair { position: absolute; left: 50%; top: 50%; width: 22px; height: 22px; transform: translate(-50%, -50%); pointer-events: none; opacity: .55; }
.crosshair.on { opacity: 1; }
.crosshair i { position: absolute; background: #fff; box-shadow: 0 0 0 1px rgba(0,0,0,.45); }
.crosshair i:nth-child(1) { left: 10px; top: 0; width: 2px; height: 7px; }
.crosshair i:nth-child(2) { left: 10px; bottom: 0; width: 2px; height: 7px; }
.crosshair i:nth-child(3) { top: 10px; left: 0; width: 7px; height: 2px; }
.crosshair i:nth-child(4) { top: 10px; right: 0; width: 7px; height: 2px; }
.hotbar { position: absolute; left: 50%; bottom: 44px; transform: translateX(-50%); display: flex; border: 1px solid var(--line); background: var(--panel); }
.hotbar button { position: relative; display: grid; place-items: center; gap: 2px; width: 62px; height: 62px; padding: 6px 2px 4px; border: 0; border-right: 1px solid var(--line); color: #4a4b44; }
.hotbar button:last-child { border-right: 0; width: 36px; }
.hotbar button.on { background: var(--text); color: var(--paper); }
.hotbar button b { position: absolute; left: 5px; top: 4px; font-size: 11px; font-weight: 600; opacity: .6; }
.hotbar button span { font-size: 12px; }
.hotbar button:hover::after { content: attr(data-label); position: absolute; bottom: 70px; left: 50%; transform: translateX(-50%); width: max-content; max-width: 240px; padding: 5px 8px; background: var(--text); color: var(--paper); font-size: 10px; letter-spacing: .04em; text-transform: none; z-index: 30; white-space: normal; }
.inventory { position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); width: min(560px, 92vw); background: var(--panel); border: 1px solid var(--line); }
.inventory header { display: flex; align-items: center; justify-content: space-between; padding: 10px 14px; border-bottom: 1px solid var(--line); }
.inventory h3 { margin: 0; font-size: 12px; color: var(--dim); border: 0; padding: 0; }
.inv-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(96px, 1fr)); margin: 12px 14px; border-top: 1px solid var(--line); border-left: 1px solid var(--line); }
.inv-grid button { display: grid; place-items: center; gap: 6px; padding: 16px 4px; border: 0; border-right: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.inv-grid button span { font-size: 12px; }
.inventory .hint { margin: 0 14px 12px; }
.island-note { position: absolute; left: 50%; bottom: 120px; transform: translateX(-50%); padding: 6px 12px; background: var(--text); color: var(--paper); font-size: 11px; letter-spacing: .08em; pointer-events: none; }

/* the galaxy bar: hidden until Esc (or the top edge) once you have dived in */
.galaxy-bar-edge { position: absolute; left: 0; right: 0; top: 0; height: 8px; z-index: 7; }
.galaxy-bar { position: absolute; left: 0; right: 0; top: 0; z-index: 8; display: flex; align-items: center; gap: 8px; height: 50px; padding: 0 14px; background: var(--panel); border-bottom: 1px solid var(--line); transform: translateY(-101%); transition: transform .18s ease; }
.galaxy-bar.open { transform: translateY(0); }
.galaxy-bar ol { list-style: none; display: flex; align-items: center; gap: 4px; margin: 0; padding: 0; color: var(--dim); }
.galaxy-bar ol button { border: 0; padding: 4px 6px; font-size: 11px; color: var(--dim); }
/* where you are: bold with an accent underline (the global dark fill of button.on made it a black block) */
.galaxy-bar ol button.on, .galaxy-bar ol button.on:hover:not(:disabled) { background: transparent; color: var(--text); border-color: transparent; font-weight: 700; box-shadow: inset 0 -2px 0 var(--accent); }
.galaxy-bar .hint { margin-left: auto; font-size: 12px; }

/* typography: Inter does the work in the tools; a grotesque with some bite (Bricolage) carries the names and titles */
:root { --font-display: 'Bricolage Grotesque', Inter, 'Helvetica Neue', Arial, sans-serif; }
.shell-brand b { font-family: var(--font-display); font-weight: 800; font-size: clamp(56px, 9vw, 128px); letter-spacing: -0.03em; line-height: .9; }
.shell-brand i { font-size: 13px; letter-spacing: .02em; font-weight: 500; text-transform: none; color: #c9c7bd; }
.shell-brand.small b { font-size: 15px; letter-spacing: -0.01em; font-weight: 800; line-height: 1; }
.shell-brand.small i { font-size: 10px; letter-spacing: .01em; text-transform: none; }
.shell-menu { border: 0; background: none; backdrop-filter: none; width: min(380px, 80vw); gap: 0; }
.shell-menu button { font-family: var(--font-display); font-weight: 600; font-size: clamp(24px, 3.2vw, 36px); letter-spacing: -0.01em; text-transform: none; padding: 12px 0 10px; border-bottom: 1px solid rgba(244,243,238,.28); color: #f4f3ee; background: none; transition: padding-left .16s ease, color .16s ease; }
.shell-menu button:hover { background: none; color: #ffb48f; padding-left: 14px; }
.shell-menu button.go { background: none; color: #f4f3ee; }
.shell-menu button.go:hover { color: #ffb48f; }
.shell-foot { text-transform: none; letter-spacing: 0; font-size: 12px; color: #a3a198; }
.shell-racing-main h2, .shell-card h3, .shell-window .shell-activity h4 { font-family: var(--font-display); letter-spacing: -0.01em; }
.shell-racing-main h2 { font-size: 34px; font-weight: 700; }
.hms .hms-logo { font-family: var(--font-display); font-weight: 800; text-transform: none; letter-spacing: -0.02em; }

.shell-note { position: absolute; left: 50%; bottom: 28px; transform: translateX(-50%); z-index: 9; max-width: min(520px, 90vw); padding: 10px 14px; background: var(--text); color: var(--paper); font-size: 13px; cursor: pointer; }
.shell-activity.current { box-shadow: inset 3px 0 0 var(--accent); }
.shell-activity input { width: 100%; font-weight: 600; }

/* lighting window: stays open beside the world so changes can be watched */
.light-win { position: absolute; right: 14px; top: 66px; bottom: 14px; width: 352px; display: flex; flex-direction: column; gap: 10px; padding: 12px; overflow-y: auto; background: var(--panel); border: 1px solid var(--line); color: var(--text); z-index: 30; }
.light-win header, .light-panel > header { display: flex; align-items: baseline; gap: 10px; }
.light-panel { display: flex; flex-direction: column; gap: 10px; }
.light-panel > header h3, .light-win header h3 { margin: 0; font: 800 20px/1 'Bricolage Grotesque', Inter, sans-serif; letter-spacing: -.01em; }
.light-panel > header .hint, .light-win header .hint { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.looks-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; }
.look { display: grid; gap: 4px; padding: 4px; text-align: left; letter-spacing: 0; }
.look i { position: relative; display: block; height: 40px; }
.look i b { position: absolute; right: 7px; top: 7px; width: 9px; height: 9px; border-radius: 50%; }
.look span { font-size: 10px; line-height: 1.2; }
.look.on { border-color: var(--accent); box-shadow: inset 0 0 0 1px var(--accent); }
.light-clock { display: grid; gap: 6px; }
.light-panel .row, .light-win .row { display: flex; align-items: center; gap: 8px; font-size: 12px; }
.light-panel footer, .light-win footer { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-top: auto; padding-top: 8px; border-top: 1px solid var(--line); }

/* the generic inspector (@hm/ui) in the white studio theme; "html " beats the stylesheet it injects itself */
html .hmi { background: transparent; color: var(--text); font: 12px/1.4 Inter, 'Helvetica Neue', Helvetica, Arial, sans-serif; padding: 0; }
html .hmi-h { color: var(--dim); font-size: 12px; font-weight: 700; margin: 10px 0 6px; padding-bottom: 5px; border-bottom: 1px solid var(--line); }
html .hmi-row, html .hmi-slot { background: transparent; border: 0; border-bottom: 1px solid var(--line); border-radius: 0; padding: 6px 0; }
html .hmi-ov { box-shadow: inset 2px 0 0 var(--accent); padding-left: 8px; }
html .hmi-label { flex-basis: 96px; }
html .hmi-in, html .hmi-num { background: #fff; color: var(--text); border: 1px solid var(--line); border-radius: 0; height: 28px; }
html .hmi-num { width: 5.4em; color: var(--text); }
html .hmi-range { height: 28px; accent-color: var(--accent); }
html .hmi-swatch { background: #fff; border: 1px solid var(--line); border-radius: 0; height: 28px; }
html .hmi-unit { color: var(--dim); }
html .hmi-src { width: 28px; height: 28px; border-radius: 0; border-color: var(--line); color: var(--dim); background: transparent; }
html .hmi-src:hover { color: var(--text); border-color: #c9c7bc; }
html .hmi-src.on { color: var(--accent); border-color: var(--accent); }
html .hmi-srcmenu { background: var(--panel); color: var(--text); border: 1px solid var(--line); }
html .hmi-srcmenu button { border: 0; padding: 7px 9px; }
html .hmi-srcmenu button:hover, html .hmi-srcmenu button.on { background: #efeee7; }
html .hmi-srcmenu button span { color: var(--dim); }
html .hmi-reset { border-radius: 0; border-color: var(--line); color: var(--accent); }
html .hmi-reset:hover { background: #efeee7; }
html .hmi-fx { background: #efeee7; color: var(--accent); border-radius: 0; }
html .hmi-chip { background: #fff; border-color: var(--line); border-radius: 0; }

/* build mode on the island: tool rail, slide-out, the words about the tool in hand, the held-Tab palette */
.tool-rail { position: absolute; left: 12px; top: 50%; transform: translateY(-50%); display: grid; gap: 0; background: var(--panel); border: 1px solid var(--line); z-index: 20; }
.tool-rail button { display: grid; place-items: center; width: 40px; height: 40px; padding: 0; border: 0; border-bottom: 1px solid var(--line); background: transparent; color: var(--dim); }
.tool-rail button:last-child { border-bottom: 0; }
.tool-rail button:hover:not(:disabled) { background: #efeee7; color: var(--text); }
.tool-rail button.held { color: var(--text); box-shadow: inset 2px 0 0 var(--text); }
.tool-rail button.open { background: var(--text); color: var(--paper); }
.tool-rail.locked { opacity: .55; pointer-events: none; }
.tool-slide { position: absolute; left: 62px; top: 50%; transform: translateY(-50%); width: 252px; max-height: 76vh; overflow-y: auto; display: grid; gap: 8px; align-content: start; padding: 12px; background: var(--panel); border: 1px solid var(--line); z-index: 20; }
.tool-slide header { display: flex; align-items: baseline; justify-content: space-between; }
.tool-slide h3 { margin: 0; font: 800 18px/1 'Bricolage Grotesque', Inter, sans-serif; }
.tool-slide h4 { margin: 8px 0 4px; font-size: 10px; font-weight: 600; color: var(--dim); }
.tool-subs { display: grid; grid-template-columns: repeat(2, 1fr); gap: 4px; }
.tool-subs button { display: flex; align-items: center; gap: 6px; padding: 6px 7px; text-align: left; font-size: 11px; }
.tool-subs button.on { background: var(--text); color: var(--paper); border-color: var(--text); }
.tool-subs button.soon { color: var(--faint); border-style: dashed; }
.tool-tune { border-top: 1px solid var(--line); padding-top: 8px; }
.tool-say { position: absolute; left: 50%; bottom: 116px; transform: translateX(-50%); display: grid; gap: 2px; justify-items: center; max-width: min(640px, 90vw); padding: 6px 12px; background: rgba(251, 250, 246, .92); border: 1px solid var(--line); text-align: center; pointer-events: none; z-index: 15; }
.tool-say b { font: 800 14px/1.2 'Bricolage Grotesque', Inter, sans-serif; }
.tool-say span { font-size: 11px; color: var(--dim); }
.tool-say .inhand i, .tool-say .btnsay i { font-style: normal; font-weight: 600; color: var(--text); margin-right: 3px; }
.tab-palette { position: absolute; right: 14px; top: 62px; width: 292px; max-height: 72vh; display: grid; gap: 8px; padding: 10px; background: var(--panel); border: 1px solid var(--text); pointer-events: none; z-index: 40; }
.tp-cats { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 10px; }
.tp-cats span { padding-bottom: 2px; color: var(--dim); font-weight: 600; font-size: 12px; border-bottom: 2px solid transparent; }
.tp-cats span.on { color: var(--text); border-bottom-color: var(--accent); }
.tp-cats em { flex-basis: 100%; font-style: normal; font-size: 10px; color: var(--dim); }
.tp-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 4px; overflow-y: auto; max-height: 52vh; }
.tp-grid div { display: grid; gap: 3px; justify-items: center; padding: 5px 2px; border: 1px solid var(--line); background: #fff; font-size: 10px; text-align: center; line-height: 1.15; }
.tp-grid div.on { border-color: var(--accent); box-shadow: inset 0 0 0 1px var(--accent); }
.tp-grid i { display: block; width: 44px; height: 44px; }
.tp-grid img { display: block; background: #f1f0ea; }

/* settings: the controls list */
.controls-list h4 { margin: 12px 0 4px; font-size: 10px; font-weight: 600; color: var(--dim); }
.controls-list dl { display: grid; margin: 0; border-top: 1px solid var(--line); }
.controls-list dl > div { display: grid; grid-template-columns: 11em 1fr; gap: 10px; padding: 5px 0; border-bottom: 1px solid var(--line); font-size: 12px; }
.controls-list dt { color: var(--dim); }
.controls-list dd { margin: 0; }

/* ---- build HUD (2026-10-03): tabs on F1..F10, slots with previews, mode buttons, windows ---- */
.hotbar button { width: 66px; height: 66px; padding: 4px 2px 3px; }
.hotbar button span { max-width: 62px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 11px; }
.hotbar button span.empty { font-size: 18px; color: var(--faint); }
.hotbar button.on span.empty { color: var(--paper); }
.tab-strip { position: absolute; left: 50%; bottom: 114px; transform: translateX(-50%); display: flex; background: var(--panel); border: 1px solid var(--line); z-index: 16; }
.tab-strip button { position: relative; display: flex; align-items: center; gap: 5px; padding: 6px 9px; border: 0; border-right: 1px solid var(--line); font-size: 11px; color: var(--dim); }
.tab-strip button:last-child { border-right: 0; }
.tab-strip button.on { background: var(--text); color: var(--paper); }
.tab-strip kbd { font: 600 10px/1 Inter, sans-serif; padding: 2px 3px; border: 1px solid currentColor; opacity: .55; }
.tab-strip button:focus-visible { outline: 2px solid var(--text); outline-offset: -2px; }
/* thirteen tabs: the open one always says its name; the others give up their words as the screen narrows (the tooltip still names them) */
.tab-strip { max-width: calc(100vw - 16px); }
@media (max-width: 1499px) { .tab-strip button:not(.on) > span { display: none; } }
@media (max-width: 999px) { .tab-strip button { padding: 6px 8px; } .tab-strip button:not(.on) kbd { display: none; } }
@media (max-width: 599px) { .tab-strip { flex-wrap: wrap; justify-content: center; } }
.tab-strip button:hover::after, .tab-strip button:focus-visible::after { content: attr(data-label); position: absolute; bottom: 36px; left: 50%; transform: translateX(-50%); width: max-content; max-width: 260px; padding: 5px 8px; background: var(--text); color: var(--paper); font-size: 10px; z-index: 30; white-space: normal; text-align: left; }
.tool-say { bottom: 156px; }
.island-note { bottom: 226px; }
.mode-bar { position: absolute; right: 14px; top: 14px; display: flex; gap: 8px; z-index: 20; }
/* the shell's slot above the galaxy bar (z 8): the toggles sit on the bar, inside its 50px, never under it */
.hud-top { position: absolute; top: 10px; right: 14px; z-index: 9; pointer-events: none; }
.hud-top > * { pointer-events: auto; }
.hud-top .mode-bar { position: static; }
.mode-bar .seg { display: flex; background: var(--panel); border: 1px solid var(--line); }
.mode-bar .seg button { border: 0; border-right: 1px solid var(--line); padding: 7px 11px; font-size: 11px; }
.mode-bar .seg button:last-child { border-right: 0; }
.island.studio .island-hint { background: rgba(36,39,34,.55); }
.tab-palette.clickable { pointer-events: auto; }
.tab-palette.clickable .tp-grid div { cursor: pointer; }
.tab-palette { top: 62px; }

/* previews */
.pv-icon { display: inline-grid; place-items: center; color: var(--text); }
.pv-swatch { display: inline-grid; grid-template-columns: 1fr 1fr; grid-template-rows: 1fr 1fr; border: 1px solid rgba(0,0,0,.12); }
.pv-swatch i { display: block; }
.pv-sky { position: relative; display: inline-block; border: 1px solid rgba(0,0,0,.08); }
.pv-sky b { position: absolute; right: 14%; top: 14%; width: 18%; height: 18%; border-radius: 50%; }
.pv-img { display: block; image-rendering: auto; }
.pv-anim line { stroke: var(--text); stroke-width: .045; stroke-linecap: round; }
.pv-anim line.ground { stroke: var(--line); stroke-width: .02; }
.pv-anim line.armR, .pv-anim line.legR { stroke: var(--accent); }
.pv-anim circle { fill: #5a9438; }
.pv-sound line { stroke: var(--line); }
.hotbar button.on .pv-anim line, .hotbar button.on .pv-icon { stroke: var(--paper); color: var(--paper); }

/* floating windows */
.fwin { position: fixed; display: flex; flex-direction: column; min-width: 220px; background: var(--panel); border: 1px solid var(--text); color: var(--text); }
.fwin > header { display: flex; align-items: center; gap: 8px; padding: 7px 8px 7px 12px; border-bottom: 1px solid var(--line); cursor: move; user-select: none; touch-action: none; }
.fwin > header h3 { flex: 1; margin: 0; font: 800 15px/1.1 'Bricolage Grotesque', Inter, sans-serif; letter-spacing: -.01em; text-transform: none; color: var(--text); border: 0; padding: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.fwin-x { display: grid; place-items: center; width: 26px; height: 26px; padding: 0; }
.fwin-body { overflow-y: auto; padding: 10px 12px 14px; }
.fwin .light-panel > header { display: none; }

/* the preset window */
.presets { display: grid; gap: 10px; }
.pw-tabs { display: flex; flex-wrap: wrap; gap: 4px; }
.pw-tabs button { display: flex; align-items: center; gap: 5px; padding: 5px 8px; font-size: 11px; }
.pw-tabs button.on { background: var(--text); color: var(--paper); border-color: var(--text); }
.pw-slots { display: grid; grid-template-columns: repeat(9, 1fr); border: 1px solid var(--line); }
.pw-slots button { position: relative; display: grid; place-items: center; height: 44px; padding: 0; border: 0; border-right: 1px solid var(--line); }
.pw-slots button:last-child { border-right: 0; }
.pw-slots button.on, .pw-slots button.on:hover:not(:disabled) { background: var(--hm-inset); color: var(--text); box-shadow: inset 0 0 0 2px var(--text); }
.pw-slots button b { position: absolute; left: 3px; top: 2px; font-size: 11px; opacity: .6; }
.pw-slots .empty { color: var(--faint); }
.pw-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(92px, 1fr)); gap: 6px; }
.pw-grid.small { grid-template-columns: repeat(auto-fill, minmax(80px, 1fr)); }
.pw-card { position: relative; display: grid; border: 1px solid var(--line); background: #fff; }
.pw-card.in { border-color: var(--text); }
.pw-pick { display: grid; justify-items: center; gap: 4px; padding: 8px 4px 6px; border: 0; text-align: center; font-size: 10px; line-height: 1.2; }
.pw-pick .badge { position: absolute; left: 4px; top: 4px; font: 600 8px/1 Inter, sans-serif; font-style: normal; color: var(--accent); }
.pw-edit { position: absolute; right: 2px; top: 2px; padding: 2px 5px; font-size: 11px; opacity: 0; }
.pw-card:hover .pw-edit, .pw-edit:focus-visible { opacity: 1; }
.presets h4 { margin: 6px 0 0; font-size: 11px; font-weight: 600; }
.pw-wide { justify-self: start; }

/* editors */
.editor { display: grid; gap: 10px; }
.ed-top { display: flex; gap: 12px; align-items: center; }
.ed-top p { margin: 0 0 6px; font-size: 12px; }
.ed-top.big { align-items: flex-start; }
.ed-moves { display: flex; flex-wrap: wrap; gap: 4px; align-items: center; }
.ed-moves button.on { background: var(--text); color: var(--paper); border-color: var(--text); }
.ed-layers { margin: 0; padding-left: 18px; font-size: 11px; color: var(--dim); }
.move-row { display: grid; grid-template-columns: 56px 1fr auto; gap: 10px; align-items: center; border-bottom: 1px solid var(--line); padding-bottom: 6px; font-size: 12px; }
.hint.warn { color: var(--danger); }

/* create your goblin */
.create-goblin { position: absolute; inset: 0; display: grid; grid-template-columns: minmax(0, 1.25fr) minmax(320px, 440px); background: linear-gradient(180deg, rgba(248,247,242,.96), rgba(241,240,234,.98)); }
.turntable { position: relative; min-height: 320px; }
.turntable canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
.cg-panel { display: flex; flex-direction: column; gap: 10px; padding: 34px 28px 24px; border-left: 1px solid var(--line); background: var(--panel); overflow-y: auto; }
.cg-panel h2 { margin: 0 0 6px; font: 800 44px/0.95 'Bricolage Grotesque', Inter, sans-serif; letter-spacing: -.02em; }
.cg-panel h4 { margin: 8px 0 0; font-size: 11px; font-weight: 600; color: var(--dim); }
.cg-name { display: grid; gap: 4px; }
.cg-name span { font-size: 11px; color: var(--dim); }
.cg-name input { font: 700 22px/1.2 'Bricolage Grotesque', Inter, sans-serif; padding: 8px 10px; }
.cg-looks { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; }
.cg-looks button { display: grid; justify-items: center; gap: 2px; padding: 6px 2px; font-size: 11px; background: #fff; }
.cg-looks button.on { color: var(--text); border-color: var(--accent); box-shadow: inset 0 0 0 1px var(--accent); }
.cg-colours { display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px; }
.cg-colours label { display: grid; justify-items: center; gap: 4px; font-size: 11px; }
.cg-colours input[type=color] { width: 100%; height: 34px; padding: 2px; }
.cg-panel .btns { display: flex; gap: 8px; align-items: center; margin-top: auto; }
.cg-panel .grow { flex: 1; }
@media (max-width: 760px) { .create-goblin { grid-template-columns: 1fr; grid-template-rows: 42vh 1fr; } .cg-panel { border-left: 0; border-top: 1px solid var(--line); } }

/* the main menu over your island: a soft dark scrim on the left keeps the menu readable over a bright day */
.shell[data-screen="menu"] .shell-ui { background: linear-gradient(90deg, rgba(8, 10, 14, .66) 0%, rgba(8, 10, 14, .38) 32%, rgba(8, 10, 14, 0) 58%); }
.shell[data-screen="menu"] .shell-foot { color: #d8d6cc; }

/* the galaxy as a star chart: the card that follows the planet under the pointer */
.planet-card { position: absolute; left: 0; top: 0; display: grid; gap: 3px; max-width: 240px; padding: 10px 12px 9px 12px; background: var(--panel); border: 1px solid var(--text); color: var(--text); pointer-events: none; z-index: 5; will-change: transform; }
.planet-card i { position: absolute; left: -1px; top: -1px; bottom: -1px; width: 4px; }
.planet-card b { font: 800 18px/1.05 'Bricolage Grotesque', Inter, sans-serif; letter-spacing: -.01em; }
.planet-card span { font-size: 12px; line-height: 1.35; }
.planet-card em { font-style: normal; font-size: 11px; color: var(--accent); }
.planet-card small { font-size: 10px; color: var(--dim); }
.shell[data-screen="hub"] .shell-top, .shell[data-screen="hub"] .shell-card { color: var(--text); }
.tree-add { display: flex; flex-wrap: wrap; gap: 4px; align-items: center; padding: 8px 10px; border-top: 1px solid var(--line); }
.tree-add small { width: 100%; color: var(--dim); }

/* plugs: what a tool sets off, and when (+ attribute) */
.plugs { display: grid; gap: 6px; border-top: 1px solid var(--line); padding-top: 10px; }
.plugs h4 { margin: 0; }
.plug { display: grid; grid-template-columns: auto auto 1fr auto auto auto; gap: 6px; align-items: center; }
.plug select { max-width: 132px; }
.plug-pv { padding: 0; border: 1px solid var(--line); background: var(--panel); line-height: 0; }
.plug-name { display: grid; font-size: 12px; line-height: 1.2; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.plug-name small { color: var(--dim); font-size: 10px; }
.plug-amt { display: flex; align-items: center; gap: 2px; font-size: 11px; color: var(--dim); }
.plug-amt input { width: 46px; }
.plug .x { min-width: 26px; min-height: 26px; padding: 2px 7px; }
.plug-choose { grid-column: 1 / -1; display: grid; grid-template-columns: repeat(auto-fill, minmax(64px, 1fr)); gap: 4px; max-height: 210px; overflow: auto; padding: 4px; border: 1px solid var(--line); }
.plug-choose button { display: grid; justify-items: center; gap: 2px; padding: 4px 2px; font-size: 10px; background: var(--panel); color: var(--text); }
.plug-choose button.on { outline: 2px solid var(--accent); outline-offset: -2px; }
.plug-choose span { max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.plug-add { justify-self: start; }
.plug-menu { display: grid; gap: 6px; padding: 8px; border: 1px solid var(--line); }
.plug-point { display: flex; flex-wrap: wrap; gap: 4px; align-items: center; }
.plug-point b { width: 100%; font-size: 12px; }
.pv-sprite .ground, .pv-anim .ground { stroke: var(--line); stroke-width: 0.01; }
.pv-sprite.glow circle { filter: drop-shadow(0 0 0.02px currentColor); }
.pv-shake rect { fill: none; stroke: var(--text); stroke-width: 0.03; }
.pv-shake line { stroke: var(--accent); stroke-width: 0.03; }

/* share with the community */
.share { display: grid; gap: 10px; }
.share-head { display: flex; gap: 12px; align-items: center; }
.share-head h3 { margin: 0 0 2px; }
.share-vis { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
.share-vis button { display: grid; gap: 3px; text-align: left; padding: 8px 10px; background: var(--panel); color: var(--text); }
.share-vis button span { font-size: 11px; color: var(--dim); line-height: 1.3; }
.share-vis button.on { outline: 2px solid var(--accent); outline-offset: -2px; }
.share .row { display: flex; gap: 8px; align-items: center; font-size: 12px; }
.share .row input { flex: 1; }
.share .row.col { flex-direction: column; align-items: stretch; }
.share textarea { font: inherit; resize: vertical; }
.share-lic { display: flex; flex-wrap: wrap; gap: 4px; list-style: none; margin: 0; padding: 0; }
.share-lic li { font-size: 11px; padding: 2px 7px; border: 1px solid var(--line); }
.share-lic li.yes { border-color: var(--text); }
.share-lic li.no { color: var(--dim); text-decoration: line-through; }
.share-problems { margin: 0; padding-left: 18px; color: var(--accent); font-size: 12px; }
.your-shares { padding: 0 12px; }
.your-shares h4 { margin: 8px 0; }

/* the island tour */
.tour { position: absolute; left: 16px; bottom: 156px; width: 300px; max-width: calc(100vw - 32px); display: grid; gap: 6px; padding: 12px 14px 10px; background: var(--panel); color: var(--text); border: 1px solid var(--text); z-index: 6; }
.tour small { color: var(--dim); font-size: 11px; }
.tour h3 { margin: 0; font: 800 20px/1.05 'Bricolage Grotesque', Inter, sans-serif; letter-spacing: -.01em; }
.tour p { margin: 0; font-size: 13px; line-height: 1.4; }
.tour-bar { height: 3px; background: var(--line); }
.tour-bar i { display: block; height: 100%; background: var(--accent); transition: width .4s ease; }
.tour-keys { display: flex; flex-wrap: wrap; gap: 4px; }
.tour kbd { font: 600 11px/1 Inter, sans-serif; padding: 4px 6px; border: 1px solid var(--text); border-bottom-width: 2px; }
.tour-btns { display: flex; gap: 6px; align-items: center; }
.tour-btns button { font-size: 12px; padding: 4px 8px; }
.tour.reveal-step { border-color: var(--accent); border-width: 2px; }
.tour-reveal { font-size: 16px; padding: 10px 14px; }
.reveal-flash { position: absolute; inset: 0; pointer-events: none; z-index: 7; background: radial-gradient(circle at 50% 60%, #fff 0%, rgba(255,255,255,.85) 40%, rgba(255,255,255,0) 75%); animation: reveal-flash 1.5s ease-out forwards; }
@keyframes reveal-flash { 0% { opacity: 0; } 12% { opacity: 1; } 100% { opacity: 0; } }
@media (prefers-reduced-motion: reduce) { .reveal-flash { animation-duration: .01s; } .tour-bar i { transition: none; } }
@media (max-width: 640px) { .tour { bottom: 150px; width: auto; right: 16px; } }

/* settings: one label column, one control column */
.shell-window > label.row { display: grid; grid-template-columns: 8.5em 1fr; gap: 10px; align-items: center; font-size: 13px; }
.shell-window > label.row:has(> input[type="checkbox"]) { display: flex; gap: 8px; }
.shell-window > label.row > select, .shell-window > label.row > input:not([type="checkbox"]) { width: 100%; min-width: 0; }
.shell-window > .controls-settings, .shell-window > .controls-list { margin: 14px 16px 0; }
.shell-window > .row.fps-target { display: grid; grid-template-columns: 8.5em 1fr; gap: 10px; align-items: center; font-size: 13px; }
.fps-target .seg { display: flex; border: 1px solid var(--line); }
.fps-target .seg button, .fps-target .seg button:first-child, .fps-target .seg button:last-child { flex: 1; border: 0; border-radius: 0; border-right: 1px solid var(--line); padding: 7px 0; font-size: 12px; }
.fps-target .seg button:last-child { border-right: 0; }
.fps-target .seg button.on, .fps-target .seg button.on:hover:not(:disabled) { background: var(--text); color: var(--paper); }
.shell-window > .graphics-tuning { margin: 12px 16px 0; padding-top: 10px; border-top: 1px solid var(--line); }
/* Settings body (shell/settings-body.tsx): the same in the main menu's Settings window and the island's movable Settings window */
.settings-body section > .row, .settings-body section > p, .settings-body section > .btns, .settings-body section > .graphics-presets { margin: 12px 16px 0; }
.settings-body section > label.row { display: grid; grid-template-columns: 8.5em 1fr; gap: 10px; align-items: center; font-size: 13px; }
.settings-body section > label.row:has(> input[type="checkbox"]) { display: flex; gap: 8px; }
.settings-body section > label.row > select, .settings-body section > label.row > input:not([type="checkbox"]) { width: 100%; min-width: 0; }
.settings-body section > .row.fps-target { display: grid; grid-template-columns: 8.5em 1fr; gap: 10px; align-items: center; font-size: 13px; }
.settings-body section > .controls-settings, .settings-body section > .controls-list, .settings-body section > .hotbar-settings { margin: 14px 16px 0; }
.settings-body section > .graphics-tuning { margin: 12px 16px 0; padding-top: 10px; border-top: 1px solid var(--line); }
.graphics-presets { display: grid; gap: 6px; font-size: 13px; }
.graphics-presets .seg { display: grid; grid-template-columns: repeat(6, 1fr); border: 1px solid var(--line); }
.graphics-presets .seg button, .graphics-presets .seg button:first-child, .graphics-presets .seg button:last-child { border: 0; border-radius: 0; border-right: 1px solid var(--line); padding: 8px 0; font-size: 12px; min-width: 0; }
.graphics-presets .seg button:last-child { border-right: 0; }
.graphics-presets .seg button.on, .graphics-presets .seg button.on:hover:not(:disabled) { background: var(--text); color: var(--paper); }
.settings-jump { display: flex; gap: 8px; }
.settings-jump button { flex: 1; }
/* inside a movable window the window's own padding is the edge */
.fwin-body > .settings-body section > *, .fwin-body > .settings-body > * { margin-left: 0; margin-right: 0; }
.graphics-tuning summary { display: flex; justify-content: space-between; gap: 12px; cursor: pointer; font-size: 13px; }
.graphics-tuning summary span { color: var(--dim); font-size: 12px; }
.graphics-tuning .graphics-reset { margin-top: 8px; }
.controls-settings h4 { margin: 0 0 4px; font-size: 10px; font-weight: 600; color: var(--dim); }

/* the Sound Lab inside an island window */
.fwin .lab { display: grid; gap: 6px; }
.fwin .lab .wave { width: 100%; height: 56px; color: var(--accent); background: #fff; border: 1px solid var(--line); display: block; }
.fwin .lab .layer { border: 1px solid var(--line); padding: 6px 8px; display: grid; gap: 4px; }
.fwin .lab .layer-head { display: flex; align-items: center; gap: 6px; }
.fwin .lab .layer-head b { flex: 1; font-size: 12px; }
.fwin .lab .row { display: flex; align-items: center; gap: 6px; font-size: 12px; }
.fwin .lab .row input[type="range"] { flex: 1; min-width: 0; }
.fwin .lab textarea.code { width: 100%; box-sizing: border-box; font: 11px/1.35 ui-monospace, Consolas, monospace; }

/* what your goblin wears */
.parts-picker { display: grid; gap: 6px; }
.pp-row { display: grid; grid-template-columns: 5.5em 1fr; gap: 6px; align-items: center; }
.pp-row b { font-size: 12px; font-weight: 600; }
.pp-cards { display: flex; gap: 4px; overflow-x: auto; padding-bottom: 2px; }
.pp-cards button { flex: 0 0 auto; padding: 2px; line-height: 0; background: var(--panel); border: 1px solid var(--line); }
.pp-cards button.none { line-height: 1; font-size: 11px; padding: 0 8px; min-height: 50px; color: var(--dim); }
.pp-cards button.on { outline: 2px solid var(--accent); outline-offset: -2px; color: var(--text); }

/* ---- SetMix Multiverse home (shell/goblin-front.tsx) --------------------------------------------------------------------------------
   The galaxy star chart is the home. SetMix speaks in Oxanium; Goblin Racing keeps its own voice (Bricolage). One bold element:
   Goblin Racing's live window, tied to its planet by a leader line like a note on a chart. Everything else stays quiet. */
:root { --font-setmix: 'Oxanium', Inter, 'Helvetica Neue', Arial, sans-serif; --ease-out: cubic-bezier(.2, .8, .2, 1); }
.sm-layer { pointer-events: none; }
.sm-layer > * { pointer-events: auto; }
.sm-home { position: absolute; inset: 0; pointer-events: none; }
.sm-home > * { pointer-events: auto; }
.sm-leader { position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none; overflow: visible; }
.sm-leader circle { fill: none; stroke: var(--text); stroke-width: 1; transition: opacity .25s; }
.sm-leader line { stroke: var(--text); stroke-width: 1; transition: opacity .25s; }
.sm-brand { position: absolute; left: clamp(20px, 5vw, 72px); top: clamp(22px, 7vh, 72px); display: flex; flex-direction: column; gap: 6px; color: var(--text); animation: sm-in .6s var(--ease-out) both; }
.sm-brand b { font-family: var(--font-setmix); font-weight: 800; font-size: clamp(48px, 7vw, 104px); letter-spacing: -0.02em; line-height: .86; }
.sm-brand i { font-family: var(--font-setmix); font-style: normal; font-weight: 500; font-size: clamp(14px, 1.3vw, 18px); color: var(--dim); padding-left: .15em; }
.sm-brand.small { position: static; flex-direction: row; align-items: baseline; gap: 10px; animation: none; }
.sm-brand.small b { font-size: 22px; }
.sm-brand.small i { font-size: 13px; }
.sm-menu { position: absolute; left: clamp(20px, 5vw, 72px); top: calc(clamp(22px, 7vh, 72px) + clamp(84px, 11vw, 160px)); display: grid; gap: 4px; width: min(340px, 80vw); }
.sm-menu button { display: grid; gap: 1px; text-align: left; padding: 8px 0 8px 0; border: 0; border-left: 2px solid transparent; background: none; color: var(--text);
  transition: padding-left .22s var(--ease-out), border-color .22s, color .22s; animation: sm-in .6s var(--ease-out) both; animation-delay: calc(120ms + var(--i, 0) * 70ms); }
.sm-menu button b { font-family: var(--font-setmix); font-weight: 600; font-size: clamp(20px, 2vw, 26px); line-height: 1.15; }
.sm-menu button small { font-size: 12px; color: var(--dim); transition: color .22s; }
.sm-menu button:hover:not(:disabled), .sm-menu button:focus-visible { background: none; padding-left: 12px; border-left-color: var(--accent); color: var(--text); outline: none; }
.sm-menu button:hover small, .sm-menu button:focus-visible small { color: var(--text); }
.sm-menu button:active:not(:disabled) { padding-left: 16px; }
.sm-menu button:disabled { cursor: default; }
.sm-menu button:disabled b { opacity: .6; }
.sm-foot { position: absolute; left: clamp(20px, 5vw, 72px); bottom: 18px; margin: 0; font-size: 12px; color: var(--dim); animation: sm-in .6s var(--ease-out) .35s both; }
/* the lab behind the SetMix home (lab/lab.tsx): revealed once, when the planet outside the arch is ready */
.lab-home { position: absolute; inset: 0; background: #0c1014; }
.lab-canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; opacity: 0; transition: opacity .9s ease; }
.lab-home.ready .lab-canvas { opacity: 1; }
.lab-loading { left: 45%; right: 5%; }
/* the menu over the lab: light type on the dim room, a soft shadow so seams behind never cut a letter */
.sm-home.lab::before { content: ""; position: absolute; inset: 0; right: auto; width: min(560px, 70vw); background: linear-gradient(90deg, rgba(12, 16, 20, .42), rgba(12, 16, 20, .2) 60%, transparent); pointer-events: none; }
.sm-home.lab .sm-brand b, .sm-home.lab .sm-menu button b, .sm-home.lab .sm-credits { color: #f1f4f5; text-shadow: 0 1px 3px rgba(10, 14, 18, .55); }
.sm-home.lab .sm-brand i, .sm-home.lab .sm-menu button small, .sm-home.lab .sm-menu .sm-sub { color: rgba(232, 238, 241, .78); text-shadow: 0 1px 2px rgba(10, 14, 18, .6); }
.sm-home.lab .sm-menu button:hover small, .sm-home.lab .sm-menu button:focus-visible small { color: #f1f4f5; }
@media (prefers-reduced-motion: reduce) { .lab-canvas { transition: none; } }
.sm-credits { position: absolute; right: 24px; top: 22px; font-family: var(--font-setmix); font-weight: 600; font-size: 14px; color: var(--text); }
.sm-layer .shell-card { left: clamp(20px, 5vw, 72px); right: auto; top: auto; bottom: 56px; width: min(320px, 80vw); animation: sm-in .35s var(--ease-out) both; }
.sm-layer .shell-card .quiet { margin-left: 8px; }
@keyframes sm-in { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }

/* ==========================================================================
   FIDELITY: Base Game Branding & Substrate Telemetry HUD
   ========================================================================== */
.fidelity-brand-lockup {
  display: flex;
  align-items: center;
  gap: clamp(14px, 1.8vw, 24px);
}
.fidelity-logo {
  width: clamp(56px, 6vw, 78px);
  height: clamp(56px, 6vw, 78px);
  flex-shrink: 0;
  transition: transform 0.3s var(--ease-out), filter 0.3s ease;
}
.fidelity-logo.glow {
  filter: drop-shadow(0 0 12px rgba(0, 229, 255, 0.4));
}
.fidelity-logo:hover {
  transform: scale(1.05);
  filter: drop-shadow(0 0 22px rgba(0, 229, 255, 0.75));
}
.fidelity-brand-text {
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.fidelity-brand-text b {
  font-family: var(--font-setmix);
  font-weight: 800;
  font-size: clamp(40px, 5.5vw, 76px);
  letter-spacing: 0.03em;
  line-height: 0.88;
  color: #f1f4f5;
  text-shadow: 0 0 24px rgba(0, 229, 255, 0.28), 0 2px 6px rgba(0, 0, 0, 0.85);
}
.fidelity-brand-text i {
  font-family: var(--font-mono, monospace);
  font-size: clamp(11px, 0.95vw, 13px);
  letter-spacing: 0.12em;
  color: #00e5ff;
  text-transform: uppercase;
  margin-top: 2px;
  opacity: 0.92;
}

.sm-menu-label-row {
  display: flex;
  align-items: center;
  gap: 10px;
}
.fidelity-badge {
  font-family: var(--font-mono, monospace);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.06em;
  padding: 1px 7px;
  border-radius: 3px;
  background: rgba(0, 229, 255, 0.12);
  color: #00e5ff;
  border: 1px solid rgba(0, 229, 255, 0.4);
  text-shadow: 0 0 6px rgba(0, 229, 255, 0.4);
}

/* Substrate Telemetry Observation Panel */
.fidelity-telemetry-hud {
  position: absolute;
  right: clamp(20px, 3.5vw, 48px);
  top: clamp(80px, 12vh, 120px);
  width: min(300px, 32vw);
  display: flex;
  flex-direction: column;
  gap: 12px;
  pointer-events: none;
  animation: sm-in 0.8s var(--ease-out) 0.2s both;
  z-index: 10;
}
.hud-panel-header {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-mono, monospace);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: rgba(232, 238, 241, 0.7);
  padding-bottom: 4px;
  border-bottom: 1px solid rgba(0, 229, 255, 0.2);
}
.hud-indicator-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #00e5ff;
  box-shadow: 0 0 8px #00e5ff;
}
.hud-indicator-dot.pulsing {
  animation: hud-pulse 2s infinite ease-in-out;
}
@keyframes hud-pulse {
  0%, 100% { opacity: 0.4; transform: scale(0.9); }
  50% { opacity: 1; transform: scale(1.2); box-shadow: 0 0 12px #00e5ff; }
}

.hud-tile {
  background: rgba(10, 16, 22, 0.65);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border: 1px solid rgba(0, 229, 255, 0.18);
  border-left: 3px solid rgba(0, 229, 255, 0.6);
  border-radius: 4px;
  padding: 10px 14px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.4);
}
.hud-tile-title {
  font-family: var(--font-mono, monospace);
  font-size: 10px;
  letter-spacing: 0.08em;
  color: rgba(232, 238, 241, 0.6);
  text-transform: uppercase;
}
.hud-tile-value {
  font-family: var(--font-mono, monospace);
  font-size: 22px;
  font-weight: 800;
  letter-spacing: 0.02em;
  line-height: 1;
}
.hud-tile-value.cyan {
  color: #00e5ff;
  text-shadow: 0 0 12px rgba(0, 229, 255, 0.5);
}
.hud-tile-value.amber {
  color: #ffb300;
  text-shadow: 0 0 12px rgba(255, 179, 0, 0.5);
}
.hud-tile-sub {
  font-family: var(--font-mono, monospace);
  font-size: 10px;
  color: rgba(232, 238, 241, 0.5);
}
.hud-meter-track {
  width: 100%;
  height: 4px;
  background: rgba(255, 255, 255, 0.08);
  border-radius: 2px;
  overflow: hidden;
  margin: 2px 0;
}
.hud-meter-bar {
  height: 100%;
  background: linear-gradient(90deg, #00e5ff, #7be7ff);
  box-shadow: 0 0 6px #00e5ff;
}
.hud-vector-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4px 10px;
  font-family: var(--font-mono, monospace);
  font-size: 11px;
  color: rgba(232, 238, 241, 0.85);
  margin: 3px 0;
}
.hud-vector-grid b {
  color: #00e5ff;
}
.hud-badge-online {
  font-family: var(--font-mono, monospace);
  font-size: 11px;
  font-weight: 700;
  color: #00e5ff;
  letter-spacing: 0.06em;
  display: flex;
  align-items: center;
  gap: 6px;
}


/* Goblin Racing's stage: a live window beside its planet on the home; open it and the same window grows to fill the screen */
/* The window: --gr-l / --gr-t are where it sits; the scene inside is moved back by the same amount on the same curve, so the 3D view stays put */
.gr-stage { --gr-w: min(42vw, 640px); --gr-l: calc(96vw - var(--gr-w)); --gr-t: 16vh; position: absolute; left: var(--gr-l); top: var(--gr-t); width: var(--gr-w); height: min(58vh, 470px);
  border: 1px solid var(--text); background: var(--paper); overflow: hidden;
  transition: top .75s var(--ease-out), left .75s var(--ease-out), width .75s var(--ease-out), height .75s var(--ease-out), border-color .75s; }
.gr-scene { position: absolute; left: calc(-1 * var(--gr-l) - 1px); top: calc(-1 * var(--gr-t) - 1px); width: 100vw; height: 100vh; transition: top .75s var(--ease-out), left .75s var(--ease-out); }
.gr-stage.full .gr-scene { left: 0; top: 0; }
/* slides in once, when it first appears (not again each time Goblin Racing shrinks back into it) */
.gr-stage.arrive { animation: gr-in .8s var(--ease-out) .25s both; }
.gr-stage.full { left: 0; top: 0; width: 100%; height: 100%; border-color: transparent; }
@keyframes gr-in { from { opacity: 0; transform: translateX(24px); } to { opacity: 1; transform: none; } }
.gr-preview { position: absolute; inset: 0; display: grid; grid-template-rows: auto 1fr auto auto; pointer-events: none; }
.gr-preview > * { pointer-events: auto; }
.gr-preview header { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 10px 8px 10px 14px; background: var(--paper); border-bottom: 1px solid var(--text); }
.gr-preview-title { display: grid; gap: 2px; min-width: 0; }
.gr-preview-name { font-family: var(--font-display); font-weight: 800; font-size: 20px; letter-spacing: -0.015em; line-height: 1; }
.gr-preview-doc { font-size: 12px; color: var(--dim); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.gr-open { border: 1px solid transparent; background: none; padding: 7px; transition: border-color .18s; }
.gr-open:hover:not(:disabled) { background: none; border-color: var(--text); }
.gr-preview-hit { position: relative; border: 0; background: transparent; cursor: zoom-in; display: grid; place-items: center; }
.gr-preview-hit:hover:not(:disabled) { background: transparent; }
.gr-cue { display: inline-flex; align-items: center; gap: 6px; padding: 7px 11px; background: var(--paper); border: 1px solid var(--text); font-size: 12px; font-weight: 600; color: var(--text);
  opacity: 0; transform: translateY(4px); transition: opacity .2s, transform .2s var(--ease-out); }
.gr-preview-hit:hover .gr-cue, .gr-preview-hit:focus-visible .gr-cue { opacity: 1; transform: none; }
.gr-preview-you { margin: 0; padding: 7px 14px; font-size: 12px; color: var(--text); background: var(--paper); border-top: 1px solid var(--text); }
.gr-preview-menu { display: grid; grid-auto-flow: column; grid-auto-columns: 1fr; background: var(--paper); border-top: 1px solid var(--line); }
.gr-preview-menu button { font-family: var(--font-display); font-weight: 700; font-size: 16px; padding: 12px 0; border: 0; border-right: 1px solid var(--line); background: none; transition: background .18s, color .18s; }
