/* keeps the words readable over bright sky and grass: dark on the left where the menu sits, clear where the goblin stands */
.gr-front .gr-scrim { position: absolute; inset: 0; pointer-events: none; background: linear-gradient(90deg, rgba(14, 18, 14, .52) 0%, rgba(14, 18, 14, .28) 32%, rgba(14, 18, 14, 0) 58%); animation: gr-fade .6s ease .35s both; }
.gr-brand { position: absolute; left: clamp(20px, 6vw, 90px); top: clamp(24px, 8vh, 80px); display: flex; flex-direction: column; color: #f6f5ef; animation: gr-rise .6s var(--ease-out) .45s both; }
