@keyframes gr-rise { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: none; } }
@keyframes gr-fade { from { opacity: 0; } to { opacity: 1; } }

@media (max-width: 760px) {
  .gr-stage { --gr-w: calc(100vw - 32px); --gr-l: 16px; --gr-t: calc(56vh - 16px); height: 44vh; }
  .sm-foot, .sm-leader { display: none; }
