  .sm-brand, .sm-menu button, .sm-foot, .gr-stage, .gr-front .gr-scrim, .gr-brand, .gr-front .shell-menu, .gr-front .shell-foot, .sm-layer .shell-card { animation: none; }
}

/* Avatars (shell/avatars.tsx) and the avatar maker's kinds: harness tools, so they speak in the SetMix voice */
.create-goblin.setmix .cg-panel h2 { font-family: var(--font-setmix); font-weight: 800; letter-spacing: -0.01em; }
.cg-kinds { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
.cg-kinds button { display: grid; gap: 2px; text-align: left; padding: 10px 12px; background: #fff; border: 1px solid var(--line); transition: border-color .18s, box-shadow .18s; }
.cg-kinds button b { font-family: var(--font-setmix); font-weight: 700; font-size: 16px; }
.cg-kinds button small { font-size: 11px; line-height: 1.3; color: var(--dim); }
.cg-kinds button:hover:not(:disabled) { background: #fff; border-color: var(--text); }
.cg-kinds button.on, .cg-kinds button.on:hover:not(:disabled) { background: #fff; color: var(--text); border-color: var(--accent); box-shadow: inset 0 0 0 1px var(--accent); }
