/* ---- avatar mode (E11): the dock beside the mirror ---- */
.avatar-dock { position: absolute; right: 16px; top: 64px; bottom: 16px; width: min(372px, calc(100vw - 32px)); display: flex; flex-direction: column; background: var(--panel); border: 1px solid var(--line); z-index: 30; overflow: hidden; }
.avatar-dock h3 { margin: 0; font-family: var(--font-setmix); font-weight: 600; font-size: 13px; color: var(--dim); text-transform: none; letter-spacing: 0; }
.ad-crew { padding: 12px 14px 10px; border-bottom: 1px solid var(--line); }
.ad-row { display: flex; gap: 6px; overflow-x: auto; padding: 8px 0 2px; scrollbar-width: thin; }
.ad-row button { flex: 0 0 74px; display: grid; justify-items: center; gap: 4px; padding: 6px 4px; background: none; border: 1px solid transparent; }
.ad-row button span { font-size: 11px; max-width: 66px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
