.ad-row .ad-new { border: 1px dashed var(--line); color: var(--dim); align-content: center; min-height: 88px; }
.ad-row .ad-new.on { border-style: solid; border-color: var(--text); color: var(--text); }
.ad-body { flex: 1; overflow: auto; padding: 14px; display: flex; flex-direction: column; gap: 10px; }
.ad-body h2 { margin: 0; font-family: var(--font-setmix); font-weight: 700; font-size: 22px; letter-spacing: -0.01em; }
