.ad-title { flex: 1; min-width: 0; font-family: var(--font-setmix); font-weight: 700; font-size: 24px; border: 0; border-bottom: 1px solid transparent; background: none; padding: 0 0 2px; color: var(--text); }
.ad-title:hover, .ad-title:focus { border-bottom-color: var(--line); outline: none; }
