.ad-name input { flex: 1; }
@media (max-width: 760px) { .avatar-dock { top: auto; height: 58vh; left: 8px; right: 8px; bottom: 8px; width: auto; } }

/* ---- making something new: three ways in (B13) ---- */
.new-chooser { display: grid; gap: 10px; }
