/* My planet on the home: your islands drawn from above, in a window placed like Goblin Racing's */
.planet-stage { position: absolute; left: calc(96vw - min(42vw, 640px)); top: 16vh; width: min(42vw, 640px); z-index: 3; border: 1px solid var(--text); background: var(--paper); animation: gr-in .5s var(--ease-out) both; }
.planet-window > header { display: flex; align-items: center; gap: 12px; padding: 10px 14px; border-bottom: 1px solid var(--text); }
