.pw-islands { display: grid; grid-template-columns: repeat(auto-fill, minmax(124px, 1fr)); gap: 8px; padding: 12px; background: var(--hm-inset); }
.pw-islands button { display: grid; justify-items: center; gap: 6px; padding: 6px; background: var(--paper); border: 1px solid var(--line); font-size: 12px; color: var(--text); }
