.planet-island.current { border-color: var(--text); }
.planet-island .pi-map { padding: 0; border: 0; background: none; justify-self: center; cursor: pointer; }
.planet-island .pi-map:hover, .planet-island .pi-map:focus-visible { background: none; outline: 1px solid var(--text); }
.planet-island h4 { margin: 0; font-family: var(--font-setmix); font-size: 17px; font-weight: 700; }
.planet-island p { margin: 0; font-size: 12px; color: var(--dim); }
.planet-island.new { display: grid; place-items: center; align-content: center; gap: 6px; min-height: 240px; border-style: dashed; color: var(--dim); font-size: 14px; }

/* a planet window whose island is still being built */
.gr-loading { position: absolute; left: 0; right: 0; top: 50%; transform: translateY(-50%); display: grid; justify-items: center; gap: 8px; font-size: 12px; color: var(--dim); pointer-events: none; }
.gr-loading i { width: 40%; height: 3px; background: var(--line); position: relative; overflow: hidden; }
.gr-loading i::after { content: ''; position: absolute; inset: 0; width: 40%; background: var(--text); animation: gr-load 1.1s ease-in-out infinite; }
@keyframes gr-load { from { transform: translateX(-100%); } to { transform: translateX(250%); } }
