.ad-row button.on { color: var(--text); }
/* panels made inside a SetMix window keep the window padding */
.shell-window > .new-island, .shell-window > .new-chooser, .shell-window > .new-activity, .shell-window > .avatar-new, .shell-window > .planet-grid { margin: 14px 16px 16px; }
.shell-window > .hint { margin-left: 16px; margin-right: 16px; }

/* ---- the hotbar's loop (docs/HOTBAR.md): the palette film strip, a tool's presets, Easy / Pro / Studio ---- */
.palette-strip { position: absolute; top: 12px; left: 50%; transform: translateX(-50%); z-index: 15; display: flex; align-items: stretch; width: min(640px, 50vw); padding: 10px 0; background: #1d1f1b; color: #f4f3ee; }
