.ps-title { align-self: center; padding: 0 8px 0 12px; font: 600 12px/1.2 var(--font-setmix); color: rgba(244, 243, 238, .75); white-space: nowrap; }
.palette-strip .ps-roll { border: 0; background: none; color: #f4f3ee; padding: 0 6px; }
