.ps-reel { display: flex; gap: 6px; flex: 1; min-width: 0; overflow-x: auto; scroll-snap-type: x proximity; scrollbar-width: none; padding: 0 2px; }
.ps-reel::-webkit-scrollbar { display: none; }
.palette-strip .ps-frame { flex: 0 0 64px; display: grid; justify-items: center; gap: 3px; padding: 5px 2px 4px; background: #2b2e28; border: 1px solid #3a3d36; color: #f4f3ee; font-size: 11px; scroll-snap-align: start; }
.ps-frame span { max-width: 60px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.palette-strip .ps-frame:hover:not(:disabled) { background: #2b2e28; border-color: rgba(244, 243, 238, .8); }
.palette-strip .ps-frame.on, .palette-strip .ps-frame.on:hover:not(:disabled) { background: #3a3d36; color: #fff; border-color: #f4f3ee; box-shadow: inset 0 0 0 1px #f4f3ee; }
.palette-strip .ps-frame .pv-icon { color: #f4f3ee; }
.ps-split { align-self: center; padding: 0 8px; font-size: 11px; color: rgba(244, 243, 238, .6); border-left: 1px solid #3a3d36; white-space: nowrap; }
.ps-empty { align-self: center; padding-right: 10px; font-size: 11px; color: rgba(244, 243, 238, .5); white-space: nowrap; }

.tool-presets { position: absolute; left: 50%; bottom: 150px; transform: translateX(-50%); z-index: 16; display: flex; align-items: stretch; max-width: min(920px, 94vw); background: var(--panel); border: 1px solid var(--line); }
.tp-say { display: grid; align-content: center; gap: 3px; min-width: 150px; padding: 6px 12px; border-right: 1px solid var(--line); }
.tp-say b { font: 700 14px/1.2 var(--font-setmix); }
.tp-say span { font-size: 11px; color: var(--dim); }
.tp-say i { font-style: normal; font-weight: 600; color: var(--text); }
.tp-list { display: flex; min-width: 0; overflow-x: auto; }
.tp-list button { display: grid; justify-items: center; gap: 3px; min-width: 66px; padding: 5px 6px 4px; border: 0; border-right: 1px solid var(--line); font-size: 11px; }
.tp-list button.on, .tp-list button.on:hover:not(:disabled) { background: var(--hm-inset); color: var(--text); box-shadow: inset 0 -2px 0 var(--text); }
.tp-pv { width: 44px; height: 44px; image-rendering: pixelated; border: 1px solid var(--line); background: var(--hm-inset); }
.tp-knobs { display: grid; align-content: center; gap: 4px; padding: 6px 10px; border-left: 1px solid var(--line); font-size: 11px; }
.tp-knobs label { display: grid; grid-template-columns: 4.6em 96px; align-items: center; gap: 6px; }
.tool-presets .tp-all { border: 0; border-left: 1px solid var(--line); padding: 0 12px; font-size: 12px; }
.hotbar .inv-btn { width: 36px; }
.hotbar .level-switch { display: grid; grid-template-rows: repeat(3, 1fr); width: 62px; border-left: 1px solid var(--line); }
