.hotbar .level-switch button:last-child { border-bottom: 0; width: 62px; }

/* My planet's screen: your islands, the looks, islands to try */
.shell-window > .planet-screen { display: grid; gap: 20px; margin: 4px 16px 16px; }
.planet-screen h3 { margin: 0 0 8px; font-family: var(--font-setmix); font-size: 17px; font-weight: 700; color: var(--text); text-transform: none; letter-spacing: 0; }
