.planet-looks { display: flex; flex-wrap: wrap; gap: 10px; }
.planet-looks button { display: grid; justify-items: center; gap: 6px; padding: 8px; background: var(--paper); border: 1px solid var(--line); color: var(--text); font-size: 13px; }
.planet-looks button.on, .planet-looks button.on:hover:not(:disabled) { background: var(--paper); color: var(--text); border-color: var(--text); box-shadow: inset 0 0 0 1px var(--text); }
.planet-tries { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 10px; }
.planet-try { display: grid; justify-items: start; gap: 4px; padding: 8px; background: var(--paper); border: 1px solid var(--line); }
.planet-try.fav { border-color: var(--text); }
.planet-try h4 { margin: 0; font-family: var(--font-setmix); font-size: 15px; font-weight: 700; }
.planet-try p { margin: 0; font-size: 12px; color: var(--dim); }
.island-map { image-rendering: pixelated; }
.island-map.smooth { image-rendering: auto; }

/* the palette's Layers button and the Layers window */
.palette-strip .ps-layers { display: grid; justify-items: center; align-content: center; gap: 2px; padding: 0 12px; border: 0; border-left: 1px solid #3a3d36; background: none; color: #f4f3ee; font-size: 11px; }
.palette-strip .ps-layers:hover:not(:disabled) { background: rgba(244, 243, 238, .12); border-color: #3a3d36; }
.layers { display: grid; gap: 8px; }
.layers .hint { margin: 0; }
.ly-head { display: flex; align-items: center; justify-content: space-between; }
.ly-head h4 { margin: 0; font-family: var(--font-setmix); font-size: 14px; font-weight: 700; }
.ly-head button { display: inline-flex; align-items: center; gap: 4px; }
.ly-list { list-style: none; margin: 0; padding: 0; border-top: 1px solid var(--line); }
.ly-row { display: flex; flex-wrap: wrap; align-items: center; gap: 2px; padding: 3px 0; border-bottom: 1px solid var(--line); }
.ly-row.hidden .ly-name { opacity: .5; }
.ly-row > button:not(.ly-name) { min-width: 28px; min-height: 28px; padding: 4px; border-color: transparent; }
.ly-name { flex: 1; min-width: 0; display: flex; align-items: center; gap: 8px; padding: 4px 6px; border: 0; background: none; text-align: left; font-size: 13px; color: var(--text); }
.ly-name small { margin-left: auto; font-size: 11px; color: var(--dim); }
.ly-row.on { background: var(--hm-inset); }
.ly-row.on .ly-name { font-weight: 600; }
.ly-attrs { flex-basis: 100%; display: grid; gap: 6px; padding: 6px 8px 8px; }
.ly-attrs label { display: grid; grid-template-columns: 4.5em 1fr; align-items: center; gap: 8px; font-size: 12px; }
.ly-attrs input[type=number] { width: 100%; }
.ly-add { display: grid; grid-template-columns: repeat(auto-fill, minmax(64px, 1fr)); gap: 4px; }
.ly-add button { display: grid; justify-items: center; gap: 2px; padding: 4px 2px; font-size: 11px; }

/* the surface editor: the tile itself is the loud thing; the controls under it stay quiet */
.surface-editor { display: grid; gap: 8px; }
.surface-editor h4 { margin: 4px 0 0; font-family: var(--font-setmix); font-size: 14px; font-weight: 700; }
.surface-editor .hint { margin: 0; }
.se-preview { width: 220px; max-width: 100%; aspect-ratio: 1; justify-self: center; border: 1px solid var(--line); display: block; }
.se-styles { display: flex; gap: 6px; overflow-x: auto; padding-bottom: 2px; }
.se-style { flex: 0 0 auto; display: grid; justify-items: center; gap: 3px; width: 66px; padding: 4px; border: 1px solid var(--line); background: var(--panel); font-size: 11px; line-height: 1.2; color: var(--text); text-align: center; }
.se-style canvas { width: 48px; height: 48px; display: block; }
.se-style.on { outline: 2px solid var(--text); outline-offset: -2px; background: var(--hm-inset); color: var(--text); }
.se-ramp { display: flex; gap: 0; border: 1px solid var(--line); }
.se-swatch { flex: 1; height: 28px; cursor: pointer; position: relative; }
.se-swatch input { position: absolute; inset: 0; opacity: 0; width: 100%; height: 100%; cursor: pointer; }
.se-swatch:focus-within { outline: 2px solid var(--text); outline-offset: -2px; }
.se-size { display: grid; grid-template-columns: 76px 1fr 72px; align-items: center; gap: 8px; font-size: 12px; }
.se-size output { color: var(--dim); font-size: 11px; text-align: right; }
.pv-tile { position: relative; overflow: hidden; }
.pv-tile img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }

/* Settings, Hotbar: the nine slots in order, each with its preview */
.hotbar-settings { display: grid; gap: 8px; }
.hs-tabs { display: flex; flex-wrap: wrap; gap: 2px; }
.hs-tabs button { padding: 4px 8px; font-size: 12px; border-color: transparent; background: none; }
.hs-tabs button.on, .hs-tabs button.on:hover:not(:disabled) { background: none; color: var(--text); border-color: transparent; box-shadow: inset 0 -2px 0 var(--accent); font-weight: 700; }
.hotbar-settings > .row { display: flex; align-items: center; gap: 10px; font-size: 13px; }
.hotbar-settings > .btns, .hotbar-settings > .hint { margin: 0; }
.hs-row { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fill, minmax(96px, 1fr)); gap: 4px; }
.hs-row li { display: grid; justify-items: center; gap: 3px; padding: 6px 4px; border: 1px solid var(--line); background: var(--panel); position: relative; font-size: 11px; }
.hs-row li.empty { border-style: dashed; color: var(--faint); }
.hs-key { position: absolute; top: 2px; left: 4px; font-size: 10px; color: var(--dim); }
.hs-blank { width: 32px; height: 32px; }
.hs-name { text-align: center; line-height: 1.2; }
.hs-acts { display: flex; gap: 2px; }
.hs-acts button { min-width: 24px; min-height: 24px; padding: 2px; border-color: transparent; }
.hs-add { display: grid; grid-template-columns: repeat(auto-fill, minmax(84px, 1fr)); gap: 4px; }
.hs-add button { display: grid; justify-items: center; gap: 3px; padding: 6px 4px; font-size: 11px; }
.se-target { justify-self: start; }
.se-preview.blocky, .se-style canvas { image-rendering: pixelated; }

/* texture mode (MASTER_PLAN 6.4): the island waits behind a white wall; the texture you stepped into is the work, three by three */
.tex-bench { position: absolute; inset: 0; display: grid; place-items: center; padding: 64px 16px 236px; background: rgba(244, 243, 238, .9); }
.tex-bench .tb-view { width: min(100%, calc(100vh - 300px)); aspect-ratio: 1; border: 1px solid var(--text); cursor: crosshair; image-rendering: auto; touch-action: none; }
.tb-head { position: absolute; top: 14px; left: 14px; display: grid; grid-template-columns: auto auto auto; align-items: center; justify-items: start; gap: 6px 8px; max-width: calc(50vw - 340px); font-family: var(--font-setmix); font-size: 14px; color: var(--dim); }
.tb-head b { color: var(--text); font-weight: 700; }
.tb-head .go { grid-column: 1 / -1; font-family: inherit; }
.se-step { justify-self: start; }
.tb-head .tb-any { grid-column: 1 / -1; display: flex; align-items: center; gap: 8px; font-family: Inter, sans-serif; font-size: 12px; color: var(--text); }
.tb-head .tb-any input { width: 36px; height: 24px; padding: 0; border: 1px solid var(--line); background: none; }

/* the island's rules (the Logic tab): a sentence each; Pro adds the blocks, Studio the script */
.logic-panel { display: grid; gap: 8px; }
.lp-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 8px; }
.lp-rule { display: grid; gap: 6px; padding: 8px 0; border-bottom: 1px solid var(--line); }
.lp-say { display: flex; align-items: flex-start; gap: 8px; font-size: 13px; line-height: 1.4; }
.lp-say span { flex: 1; }
.lp-say button { min-width: 28px; min-height: 28px; padding: 4px; border-color: transparent; }
.lp-blocks { display: flex; flex-wrap: wrap; gap: 4px; }
.lp-block { display: inline-flex; align-items: center; gap: 4px; padding: 3px 6px; border: 1px solid var(--line); background: var(--panel); font-size: 12px; }
.lp-block.when { border-left: 3px solid var(--gold); }
.lp-block.do { border-left: 3px solid var(--green); }
.lp-block input[type="number"] { width: 56px; }
.lp-script { margin: 0; padding: 8px; background: #1d1f1b; color: #e8e6dc; font-size: 11px; line-height: 1.45; overflow-x: auto; white-space: pre; }

/* Box (Select, F1): the rectangle you drag over things */
.box-select { position: absolute; border: 1px solid #ffc53d; background: rgba(255, 197, 61, .12); pointer-events: none; z-index: 14; }

/* ---------------------------------------------------------------------------------------------------------------------------------
   The V3 hotbar (docs/HOTBAR_V3_SPEC.md): one column at the bottom, read upward: the slots, the F1..F12 tabs, then what the mode shows
   (Game: the words of the preset in hand; Simplified: presets and sliders; Advanced: options, filters, keys). Square, white wall, quiet.
   The one loud thing is Game Mode's number keys; the only colour is the accent under the slot in hand.
   --------------------------------------------------------------------------------------------------------------------------------- */
.v3 { position: absolute; left: 50%; bottom: 44px; transform: translateX(-50%); z-index: 16; display: flex; flex-direction: column; align-items: center; gap: 6px; width: max-content; max-width: calc(100vw - 16px); pointer-events: none; }
.v3 > * { pointer-events: auto; }
.v3 .island-note { position: static; transform: none; pointer-events: none; }
.v3 button { position: relative; font-family: Inter, sans-serif; color: var(--text); background: transparent; border-radius: 0; box-shadow: none; }
.v3 button:focus-visible { outline: 2px solid var(--accent); outline-offset: -2px; }
.v3 [data-label]:hover::after, .v3 [data-label]:focus-visible::after { content: attr(data-label); position: absolute; bottom: calc(100% + 6px); left: 50%; transform: translateX(-50%); width: max-content; max-width: 260px; padding: 5px 8px; background: var(--text); color: var(--paper); font: 400 11px/1.35 Inter, sans-serif; text-align: left; white-space: normal; z-index: 30; pointer-events: none; }
.v3 .v3-pip { position: absolute; right: 4px; top: 4px; width: 6px; height: 6px; border: 1.5px solid currentColor; opacity: .6; }
.v3 .v3-label { font-size: 11px; color: var(--dim); white-space: nowrap; }

/* the tabs */
.v3-tabs { display: flex; max-width: calc(100vw - 16px); background: var(--panel); border: 1px solid var(--line); }
.v3-tabs button { display: flex; align-items: center; gap: 5px; padding: 6px 9px; border: 0; border-right: 1px solid var(--line); font-size: 11px; color: var(--dim); white-space: nowrap; }
.v3-tabs button:last-child { border-right: 0; }
.v3-tabs button.on { background: var(--text); color: var(--paper); }
.v3-tabs kbd { font: 600 10px/1 Inter, sans-serif; padding: 2px 3px; border: 1px solid currentColor; opacity: .55; }

/* the slots and the end of the bar */
.v3-bar { display: flex; align-items: stretch; gap: 6px; }
.v3-slots { display: flex; background: var(--panel); border: 1px solid var(--line); }
.v3-slot { display: grid; place-items: center; align-content: center; gap: 3px; width: 72px; height: 64px; padding: 14px 4px 5px; border: 0; border-right: 1px solid var(--line); color: #4a4b44; }
.v3-slot:last-child { border-right: 0; }
.v3-slot > span { max-width: 100%; font-size: 10.5px; line-height: 1.15; text-align: center; overflow: hidden; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
.v3-slot .v3-num { position: absolute; left: 6px; top: 4px; font: 600 11px/1 var(--font-setmix); opacity: .6; }
.v3 .v3-slot.on { background: var(--text); color: var(--paper); }
.v3-slot.coming:not(.on) > svg, .v3-slot.coming:not(.on) > span { opacity: .45; }
.v3-end { display: flex; align-items: stretch; gap: 6px; }
.v3 .v3-icon { display: grid; place-items: center; width: 34px; background: var(--panel); border: 1px solid var(--line); }
.v3 .v3-icon[aria-expanded="true"] { background: var(--text); color: var(--paper); }
.v3-modes { display: flex; background: var(--panel); border: 1px solid var(--line); }
.v3 .v3-modes button { padding: 0 12px; border: 0; border-right: 1px solid var(--line); font: 600 12px/1 var(--font-setmix); color: var(--dim); }
.v3 .v3-modes button:last-child { border-right: 0; }
.v3 .v3-modes button.on { background: var(--text); color: var(--paper); }

/* Game Mode: toy number keys, the loud part; the key in hand sits on the accent */
.v3-game .v3-slot { width: 80px; height: 76px; padding-top: 22px; box-shadow: inset 0 -3px 0 var(--line); }
.v3-game .v3-slot .v3-num { left: 7px; top: 3px; font: 700 22px/1 var(--font-setmix); letter-spacing: -.02em; opacity: .9; }
.v3 .v3-game .v3-slot.on, .v3-game .v3-slot.on { box-shadow: inset 0 -3px 0 var(--accent); }
.v3-say { display: grid; gap: 2px; justify-items: center; max-width: min(640px, 92vw); padding: 6px 14px; background: rgba(251, 250, 246, .94); border: 1px solid var(--line); text-align: center; }
.v3-say b { font: 700 16px/1.2 var(--font-setmix); }
.v3-say > span { font-size: 11.5px; color: var(--dim); }
.v3-mouse { font-size: 11px; color: var(--dim); white-space: nowrap; }
.v3-mouse i { font-style: normal; font-weight: 600; color: var(--text); margin: 0 3px 0 8px; }
.v3-mouse i:first-child { margin-left: 0; }

/* Simplified Mode: sub-tools named in full; presets and sliders above them */
.v3-simplified .v3-slot { grid-auto-flow: column; justify-content: start; gap: 8px; width: auto; min-width: 132px; height: 50px; padding: 0 16px 0 26px; }
.v3-simplified .v3-slot > span { font-size: 12px; text-align: left; }
.v3-simplified .v3-slot .v3-num { top: 50%; transform: translateY(-50%); left: 8px; font-size: 13px; }
.v3-panel { display: grid; gap: 8px; width: min(820px, calc(100vw - 16px)); padding: 8px 10px 10px; background: var(--panel); border: 1px solid var(--line); }
.v3-panel > header { display: flex; align-items: baseline; gap: 10px; min-width: 0; }
.v3-panel > header b { font: 700 15px/1.2 var(--font-setmix); white-space: nowrap; }
.v3-panel > header .v3-sub { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 12px; color: var(--dim); }
.v3-panel > header .v3-mouse { margin-left: auto; }
.v3-chips, .v3-filters { display: flex; flex-wrap: wrap; gap: 4px; }
.v3 .v3-chips button, .v3 .v3-filters button { min-height: 26px; padding: 3px 10px; border: 1px solid var(--line); font-size: 12px; line-height: 1.25; text-align: left; }
.v3 .v3-chips button.on { background: var(--text); border-color: var(--text); color: var(--paper); }
.v3 .v3-chips button.coming, .v3 .v3-filters button.coming { border-style: dashed; color: var(--dim); padding-right: 16px; }
.v3 .v3-filters button { color: var(--dim); }
.v3 .v3-filters button.on:not(.coming) { color: var(--text); border-color: var(--text); background: #ecebe4; }
.v3-sliders { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 16px; }
.v3-range { display: grid; grid-template-columns: auto 132px 58px; align-items: center; gap: 8px; }
.v3-range output { font: 600 12px/1 var(--font-setmix); font-variant-numeric: tabular-nums; text-align: right; }
.v3-sliders .coming { opacity: .45; }
.v3 .v3-toggle { display: inline-flex; align-items: center; gap: 8px; height: 26px; padding: 0 8px; border: 1px solid var(--line); font-size: 12px; }
.v3-toggle i { font-style: normal; font-weight: 600; color: var(--dim); }
.v3 .v3-toggle.on { border-color: var(--text); }
.v3-toggle.on i { color: var(--text); }
.v3-choice { display: inline-flex; align-items: center; }
.v3-choice .v3-label { margin-right: 8px; }
.v3 .v3-choice button { height: 26px; padding: 0 8px; border: 1px solid var(--line); margin-left: -1px; font-size: 11.5px; }
.v3 .v3-choice button.on { background: var(--text); border-color: var(--text); color: var(--paper); }
.v3-colour { display: inline-flex; align-items: center; gap: 8px; }
.v3-colour input { width: 34px; height: 24px; padding: 0; border: 1px solid var(--line); background: none; }
.v3 .v3-reset { margin-left: auto; height: 26px; padding: 0 10px; border: 1px solid var(--line); font-size: 11.5px; }
.v3 .v3-reset:disabled { opacity: .4; }

/* the options a tool picks from (Advanced, and Game's Prop Box) */
.v3-options { display: flex; align-items: center; gap: 8px; min-width: 0; max-width: min(820px, calc(100vw - 16px)); padding: 6px 8px; background: var(--panel); border: 1px solid var(--line); }
.v3-panel .v3-options { padding: 0; border: 0; background: none; }
.v3-scroll { display: flex; gap: 4px; min-width: 0; overflow-x: auto; scrollbar-width: thin; }
.v3 .v3-options button { display: inline-flex; align-items: center; gap: 6px; flex: 0 0 auto; height: 30px; padding: 0 9px 0 4px; border: 1px solid var(--line); font-size: 11.5px; white-space: nowrap; }
.v3 .v3-options button.on { border-color: var(--text); box-shadow: inset 0 -2px 0 var(--accent); }

/* Advanced Mode: compact tools; the keys of the tab, as a legend */
.v3-advanced .v3-slot { width: 62px; height: 54px; padding-top: 12px; }
.v3-advanced .v3-slot > span { font-size: 9.5px; }
.v3 .v3-advanced .v3-chips button, .v3-advanced .v3-chips button { font-size: 11px; padding: 2px 8px; min-height: 24px; }
.v3-keys { display: flex; flex-wrap: wrap; gap: 4px 16px; margin: 0; }
.v3-keys > div { display: flex; align-items: center; gap: 6px; font-size: 11px; }
.v3-keys dt, .v3-keys dd { margin: 0; }
.v3-keys dd { color: var(--dim); }
.v3-keys kbd { font: 600 10px/1 Inter, sans-serif; padding: 2px 4px; border: 1px solid currentColor; }
.v3-keys .coming { opacity: .5; }

/* Find a tool (/) */
.v3-find { width: min(440px, calc(100vw - 16px)); background: var(--panel); border: 1px solid var(--text); }
.v3-find input { width: 100%; height: 40px; padding: 0 12px; border: 0; border-bottom: 1px solid var(--line); background: none; font: 600 15px/1 var(--font-setmix); color: var(--text); }
.v3-find input:focus { outline: none; }
.v3-find ul { list-style: none; margin: 0; padding: 4px 0; max-height: 280px; overflow-y: auto; }
.v3-find li { display: flex; align-items: baseline; justify-content: space-between; gap: 14px; padding: 6px 12px; cursor: pointer; }
.v3-find li.on { background: #ecebe4; }
.v3-find li b { font-size: 13px; font-weight: 600; }
.v3-find li span { font-size: 11px; color: var(--dim); white-space: nowrap; }
.v3-find li.coming b { color: var(--dim); }
.v3-find .v3-none { margin: 0; padding: 10px 12px; font-size: 12px; color: var(--dim); }

@media (max-width: 1499px) { .v3-tabs kbd { display: none; } .v3-tabs button { padding: 6px 8px; gap: 4px; } }
@media (max-width: 1099px) {
  .v3-tabs button:not(.on) > span { display: none; }
  .v3-tabs button:not(.on) kbd { display: inline; }
  .v3-game .v3-slot { width: 62px; padding-top: 18px; }
  .v3-advanced .v3-slot > span { display: none; }
  .island.hud .island-hint { display: none; }
  .v3-simplified .v3-slot { min-width: 0; padding: 0 10px 0 22px; }
  .v3-range { grid-template-columns: auto 96px 50px; }
}
@media (max-width: 720px) {
  .v3-bar, .v3-tabs { flex-wrap: wrap; justify-content: center; }
  .v3-simplified .v3-slot > span, .v3-game .v3-slot > span { display: none; }
  .v3-simplified .v3-slot { padding: 0 12px 0 24px; }
  .v3-panel > header .v3-mouse { display: none; }
}
/* while the hotbar is up, the shell's notes speak from the top (at the bottom they would sit on the slots) */
body:has(.island.hud) .shell-note { bottom: auto; top: 64px; }

/* the Visual Wire Graph (Advanced F7): read left to right like a sentence; the only colour is the cord's purple, as in the world */
.wg { display: grid; grid-template-rows: minmax(0, 1fr) auto; height: 100%; min-height: 0; gap: 8px; }
.wg-canvas { overflow: auto; background: var(--panel); border: 1px solid var(--line); min-height: 0; }
.wg svg { display: block; touch-action: none; user-select: none; }
.wg .node > rect:first-child { fill: var(--panel); stroke: var(--line); }
.wg .node.zone .bar { fill: #8e6be8; }
.wg .node .title { font: 600 12px/1 Inter, sans-serif; fill: var(--text); }
.wg .node .sub { font: 400 10px/1 Inter, sans-serif; fill: var(--dim); }
.wg .port { fill: #8e6be8; cursor: crosshair; }
.wg .port.open { fill: var(--panel); stroke: #8e6be8; stroke-dasharray: 2 2; cursor: default; }
.wg .cord { fill: none; stroke: #8e6be8; stroke-width: 2; opacity: .55; pointer-events: none; }
.wg .cord.on { stroke-width: 3.5; opacity: 1; }
.wg .hit { fill: none; stroke: transparent; stroke-width: 14; cursor: pointer; }
.wg .wire { outline: none; }
.wg .wire:focus-visible .cord { stroke-width: 3.5; opacity: 1; stroke-dasharray: 6 3; }
.wg-bar { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; font-size: 12px; min-height: 28px; }
.wg-bar .dim { color: var(--dim); }
.wg-empty { padding: 16px; color: var(--dim); font-size: 12px; max-width: 46ch; }
@media (prefers-reduced-motion: reduce) { .wg * { transition: none !important; } }

/* the island budget (build/budget.ts): a slim square meter by Find; the accent only when nearly full */
.v3-budget { align-self: center; width: 46px; height: 6px; border: 1px solid var(--line); background: var(--paper); position: relative; }
.v3-budget i { position: absolute; inset: 0 auto 0 0; background: var(--text); }
.v3-budget.full i { background: var(--accent); }

/* ---- Profile chip and dropdown menu (TASK-09) ---- */
.sm-top-controls {
  position: absolute;
  right: 24px;
  top: 18px;
  display: flex;
  align-items: center;
  gap: 12px;
  z-index: 20;
}
.sm-top-controls .sm-credits {
  position: static;
  font-family: var(--font-setmix);
  font-weight: 600;
  font-size: 14px;
  color: #f1f4f5;
  text-shadow: 0 1px 3px rgba(10, 14, 18, .55);
}

.sm-profile-container {
  position: relative;
}

.sm-profile-chip {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-family: var(--font-setmix);
