/*
 * The Studio: a dark desktop editor in the game's telemetry look. Everything is scoped under .sx, because the global
 * studio.css (warm, light) and shell.css style bare buttons, inputs and tables for the rest of the game.
 * Palette: near-black blue glass, hairline slate rules, the game's amber accent for what is selected or changed, cyan
 * for the readout. Oxanium for the brand and panel titles and the telemetry numbers; Inter for everything else.
 */
.sx {
  --sx-bg: #05080c;
  --sx-panel: rgba(12, 17, 24, 0.86);
  --sx-raise: rgba(20, 28, 38, 0.9);
  --sx-line: #1c2734;
  --sx-line-hi: #2c3d51;
  --sx-text: #d7e3ee;
  --sx-dim: #6c8193;
  --sx-amber: #ffc53d;
  --sx-amber-soft: rgba(255, 197, 61, 0.14);
  --sx-cyan: #5fd4ff;
  --sx-ok: #6fe3a0;
  --sx-err: #ff7a6b;
  --sx-display: Oxanium, 'Segoe UI', system-ui, sans-serif;
  --sx-ui: Inter, 'Segoe UI', system-ui, sans-serif;

  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  background:
    radial-gradient(1200px 500px at 12% -10%, rgba(255, 197, 61, 0.05), transparent 60%),
    radial-gradient(900px 600px at 100% 110%, rgba(95, 212, 255, 0.05), transparent 60%),
    var(--sx-bg);
  color: var(--sx-text);
  font: 400 13px/1.45 var(--sx-ui);
  -webkit-font-smoothing: antialiased;
  overflow: hidden;
  text-align: left;
}
.sx *, .sx *::before, .sx *::after { box-sizing: border-box; }
.sx h2, .sx h3, .sx h4, .sx p { margin: 0; }
.sx h2 { font: 600 13px/1 var(--sx-display); letter-spacing: 0.04em; color: var(--sx-text); }
.sx h3 { font: 600 15px/1.2 var(--sx-display); color: var(--sx-text); }
.sx h4 { font: 600 11px/1 var(--sx-display); color: var(--sx-dim); letter-spacing: 0.08em; text-transform: none; margin: 18px 0 8px; }
.sx-dim { color: var(--sx-dim); }
.sx-grow { flex: 1; }
.sx-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }
.sx-count { font: 600 11px/1 var(--sx-display); color: var(--sx-amber); margin-left: 6px; font-variant-numeric: tabular-nums; }
.sx-hot { color: var(--sx-amber); }
.sx-num-cell { font-variant-numeric: tabular-nums; white-space: nowrap; }

/* controls */
.sx button, .sx select, .sx input { font: 500 12px/1 var(--sx-ui); color: var(--sx-text); }
.sx button {
  background: var(--sx-raise);
  border: 1px solid var(--sx-line-hi);
  border-radius: 6px;
  padding: 7px 11px;
  cursor: pointer;
  transition: background 0.12s, border-color 0.12s, box-shadow 0.12s, color 0.12s;
  white-space: nowrap;
}
.sx button:hover:not(:disabled) { background: #243243; border-color: #3a4f66; }
.sx button:focus-visible, .sx input:focus-visible, .sx select:focus-visible, .sx .sx-split:focus-visible { outline: 2px solid var(--sx-cyan); outline-offset: 2px; }
.sx button:disabled { opacity: 0.38; cursor: default; }
.sx button[aria-pressed='true'] { background: var(--sx-amber-soft); border-color: rgba(255, 197, 61, 0.55); color: var(--sx-amber); box-shadow: 0 0 14px rgba(255, 197, 61, 0.12); }
.sx button.sx-go { background: linear-gradient(180deg, #ffd060, #e9a92a); border-color: #ffd060; color: #1b1403; font-weight: 600; box-shadow: 0 0 16px rgba(255, 197, 61, 0.22); }
.sx button.sx-go:hover:not(:disabled) { background: linear-gradient(180deg, #ffdb7a, #f0b43c); }
.sx button.sx-mini { padding: 3px 7px; font-size: 11px; border-radius: 4px; }
.sx kbd { font: 600 10px/1 var(--sx-display); color: var(--sx-dim); border: 1px solid var(--sx-line-hi); border-radius: 3px; padding: 2px 4px; margin-left: 2px; }
.sx input[type='number'], .sx input[type='text'], .sx input[type='search'] {
  background: #0a1017;
  border: 1px solid var(--sx-line-hi);
  border-radius: 5px;
  padding: 6px 8px;
  font-variant-numeric: tabular-nums;
  min-width: 0;
}
.sx input[type='number']::-webkit-inner-spin-button { opacity: 0.4; }
.sx input[type='color'] { width: 34px; height: 26px; padding: 0; background: none; border: 1px solid var(--sx-line-hi); border-radius: 5px; cursor: pointer; }
.sx select { background: #0a1017; border: 1px solid var(--sx-line-hi); border-radius: 6px; padding: 6px 8px; }
.sx input[type='range'] { width: 100%; accent-color: var(--sx-amber); margin: 8px 0 2px; }
.sx .sx-seg { display: inline-flex; border: 1px solid var(--sx-line-hi); border-radius: 6px; overflow: hidden; background: #0a1017; }
.sx .sx-seg button { border: 0; border-radius: 0; background: transparent; }
.sx .sx-seg button + button { border-left: 1px solid var(--sx-line-hi); }
.sx .sx-seg button[aria-pressed='true'] { box-shadow: inset 0 -2px 0 var(--sx-amber); }

/* top bar */
.sx-top {
  display: flex;
  align-items: center;
  gap: 10px;
  height: 52px;
  padding: 0 12px;
  background: linear-gradient(180deg, rgba(16, 23, 32, 0.96), rgba(10, 14, 20, 0.96));
  border-bottom: 1px solid var(--sx-line);
  box-shadow: 0 1px 0 rgba(255, 197, 61, 0.06);
  flex: 0 0 auto;
  min-width: 0;
}
.sx-brand { display: flex; align-items: center; gap: 9px; padding-right: 12px; border-right: 1px solid var(--sx-line); }
.sx-brand b { display: block; font: 700 13px/1 var(--sx-display); letter-spacing: 0.14em; color: var(--sx-text); }
.sx-brand span { display: block; font: 500 11px/1.2 var(--sx-display); color: var(--sx-amber); letter-spacing: 0.06em; margin-top: 3px; }
.sx-mark { width: 14px; height: 14px; border: 2px solid var(--sx-amber); transform: rotate(45deg); box-shadow: 0 0 12px rgba(255, 197, 61, 0.55); }
.sx-tabs { display: flex; gap: 2px; }
.sx-tabs button { background: transparent; border: 1px solid transparent; border-radius: 6px; padding: 7px 11px; color: var(--sx-dim); font: 600 12px/1 var(--sx-display); letter-spacing: 0.03em; }
.sx-tabs button:hover:not(:disabled) { color: var(--sx-text); background: rgba(255, 255, 255, 0.03); }
.sx-tabs button[aria-pressed='true'] { color: var(--sx-amber); background: var(--sx-amber-soft); border-color: rgba(255, 197, 61, 0.4); }
.sx-tabs button:disabled { opacity: 0.45; }
.sx-tabs button i { font: 500 9px/1 var(--sx-ui); font-style: normal; color: var(--sx-dim); margin-left: 6px; }
.sx-cluster { display: flex; align-items: center; gap: 6px; }
.sx-select { display: inline-flex; align-items: center; gap: 6px; color: var(--sx-dim); font-size: 11px; }

.sx-banner {
  padding: 7px 14px;
  background: rgba(255, 197, 61, 0.1);
  border-bottom: 1px solid rgba(255, 197, 61, 0.35);
  color: #ffe2a0;
  font-size: 12px;
  flex: 0 0 auto;
}

/* the body: left, centre (viewport over changes), right */
.sx-body {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: var(--l) 6px minmax(0, 1fr) 6px var(--r);
}
.sx-panel {
  background: var(--sx-panel);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  min-height: 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}
.sx-left { border-right: 0; }
/* the details panel scrolls down only: a wider child must not scroll the tab row out from under the viewport's toolbar */
.sx-right { overflow-y: auto; overflow-x: clip; padding: 14px 14px 22px; }
.sx-block { display: flex; flex-direction: column; min-height: 0; padding: 12px 12px 10px; }
.sx-block + .sx-block { border-top: 1px solid var(--sx-line); }
.sx-block h2 { margin-bottom: 10px; }
.sx-block-head { display: flex; align-items: baseline; justify-content: space-between; margin-bottom: 12px; }
.sx-outline { flex: 0 0 auto; max-height: 45%; overflow: auto; }
.sx-split { background: transparent; position: relative; z-index: 2; }
.sx-split.vertical { cursor: col-resize; }
.sx-split.horizontal { cursor: row-resize; height: 6px; background: var(--sx-line); }
.sx-split:hover, .sx-split:focus-visible { background: rgba(255, 197, 61, 0.4); }
.sx-split.vertical::after { content: ''; position: absolute; inset: 0 2px; background: var(--sx-line); }
.sx-split.vertical:hover::after { background: rgba(255, 197, 61, 0.4); }

.sx-browser { display: flex; flex-direction: column; min-height: 0; flex: 1; }
.sx-search { width: 100%; margin-bottom: 6px; }
.sx-count-note { margin-bottom: 6px; }
.sx-list { list-style: none; margin: 0; padding: 0; overflow: auto; min-height: 0; flex: 1; }
.sx-browser .sx-list { margin-top: 6px; }
.sx-row { display: flex; align-items: center; gap: 4px; border-bottom: 1px solid rgba(28, 39, 52, 0.7); }
.sx-row-main {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  background: transparent;
  border: 0;
  border-radius: 0;
  padding: 7px 6px;
  text-align: left;
}
.sx-row-main:hover:not(:disabled) { background: rgba(255, 255, 255, 0.03); border: 0; }
.sx-row-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.sx-row.on { background: var(--sx-amber-soft); box-shadow: inset 2px 0 0 var(--sx-amber); }
.sx-row.on .sx-row-name { color: var(--sx-amber); }
.sx-row .sx-dim { font-size: 11px; white-space: nowrap; }
.sx-tag { font-size: 10px; color: var(--sx-cyan); border: 1px solid rgba(95, 212, 255, 0.35); border-radius: 3px; padding: 1px 4px; margin-right: 4px; }
.sx-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--sx-amber); box-shadow: 0 0 8px var(--sx-amber); flex: 0 0 auto; align-self: center; }
.sx-outliner .sx-row { padding-right: 4px; }
.sx-empty { padding: 8px 0; }

/* the centre: viewport over the changes panel */
