/* The nine-zone HUD and its six fidelity skins (TASK-25; Argo's plans 16 and 28).
 * One switch: the play root carries data-fidelity ("0a" | "0b" | "1" | "2" | "3" | "4-6"). Every skin is a set of CSS
 * variables on the same components, and no skin moves a zone. The default (no attribute) is the 4-6 telemetry glass. */

/* 1. The skin tokens (plan 28, section 3). The bare root is 4-6, so an unskinned screen looks as it did. */
.play {
  --hud-font-display: 'Oxanium', sans-serif;
  --hud-font-body: 'Inter', sans-serif;
  --hud-bg: rgba(10, 15, 24, 0.72);
  --hud-backdrop: blur(12px) saturate(140%);
  --hud-border: 1px solid rgba(255, 255, 255, 0.16);
  --hud-radius: 8px;
  --hud-shadow: 0 8px 28px rgba(0, 0, 0, 0.55), 0 0 16px rgba(61, 200, 255, 0.08);
  --hud-text: #f4f8ff;
  --hud-text-dim: #94a3b8;
  --hud-c-pxd: #ff3d8a;
  --hud-c-vtx: #7cff4d;
  --hud-c-lx: #ffc13d;
  --hud-c-aq: #3dc8ff;
  --hud-c-mix: #b46bff;
  --hud-bar-pattern: linear-gradient(90deg, currentColor, currentColor);
}

/* 0a, vector: hairline phosphor on black, no fills, a monospace vector face. */
.play[data-fidelity='0a'] {
  --hud-font-display: 'Share Tech Mono', monospace;
  --hud-font-body: 'Share Tech Mono', monospace;
  --hud-bg: rgba(5, 6, 8, 0.9);
  --hud-backdrop: none;
  --hud-border: 1px solid #e8eef5;
  --hud-radius: 0px;
  --hud-shadow: 0 0 6px rgba(232, 238, 245, 0.35);
  --hud-text: #e8eef5;
  --hud-text-dim: #9aa8b8;
  --hud-c-pxd: #ff5599;
  --hud-c-vtx: #7cff4d;
  --hud-c-lx: #ffc13d;
  --hud-c-aq: #3dc8ff;
  --hud-c-mix: #b46bff;
  --hud-bar-pattern: none;
}

/* 0b, 1-bit: solid black and white, a hard offset shadow, Bayer-dithered gauges. */
.play[data-fidelity='0b'] {
  --hud-font-display: 'Share Tech Mono', monospace;
  --hud-font-body: 'Share Tech Mono', monospace;
  --hud-bg: #050608;
  --hud-backdrop: none;
  --hud-border: 2px solid #e8eef5;
  --hud-radius: 0px;
  --hud-shadow: 3px 3px 0px #e8eef5;
  --hud-text: #e8eef5;
  --hud-text-dim: #b0bccb;
  --hud-c-pxd: #ff3d8a;
  --hud-c-vtx: #7cff4d;
  --hud-c-lx: #ffc13d;
  --hud-c-aq: #3dc8ff;
  --hud-c-mix: #b46bff;
  --hud-bar-pattern: repeating-conic-gradient(currentColor 0% 25%, #050608 0% 50%) 0 0 / 4px 4px;
}

/* 1, 16-colour EGA: navy panels, a double box-drawn border, stepped block gauges in the hardware hues. */
.play[data-fidelity='1'] {
  --hud-font-display: 'Share Tech Mono', monospace;
  --hud-font-body: 'Share Tech Mono', monospace;
  --hud-bg: rgba(10, 14, 26, 0.94);
  --hud-backdrop: none;
  --hud-border: 3px double #a8b8d0;
  --hud-radius: 0px;
  --hud-shadow: 4px 4px 0px #000000;
  --hud-text: #ffffff;
  --hud-text-dim: #55ffff;
  --hud-c-pxd: #ff55ff;
  --hud-c-vtx: #55ff55;
  --hud-c-lx: #ffff55;
  --hud-c-aq: #55ffff;
  --hud-c-mix: #aa55ff;
  --hud-bar-pattern: linear-gradient(90deg, currentColor 75%, transparent 75%) 0 0 / 12.5% 100%;
}

/* 2, 256-colour VGA: gunmetal panels with a chiselled bevel and recessed wells. */
.play[data-fidelity='2'] {
  --hud-font-display: 'Oxanium', sans-serif;
  --hud-font-body: 'Inter', sans-serif;
  --hud-bg: rgba(24, 28, 36, 0.94);
  --hud-backdrop: none;
  --hud-border: 2px solid #6c7a89;
  --hud-radius: 2px;
  --hud-shadow: inset 1px 1px 0 #8a99ad, 2px 2px 0 #000000;
  --hud-text: #f0f4f8;
  --hud-text-dim: #a0aec0;
  --hud-c-pxd: #ff3d8a;
  --hud-c-vtx: #7cff4d;
  --hud-c-lx: #ffc13d;
  --hud-c-aq: #3dc8ff;
  --hud-c-mix: #b46bff;
  --hud-bar-pattern: none;
}

/* 3, 16-bit Gouraud: slate glass, rounded corners, smooth gradient bars. */
.play[data-fidelity='3'] {
  --hud-font-display: 'Oxanium', sans-serif;
  --hud-font-body: 'Inter', sans-serif;
  --hud-bg: rgba(14, 20, 32, 0.84);
  --hud-backdrop: blur(4px);
  --hud-border: 1px solid rgba(140, 180, 220, 0.35);
  --hud-radius: 4px;
  --hud-shadow: 0 4px 14px rgba(0, 0, 0, 0.45);
  --hud-text: #f0f6fc;
  --hud-text-dim: #94a3b8;
  --hud-c-pxd: #ff3d8a;
  --hud-c-vtx: #7cff4d;
  --hud-c-lx: #ffc13d;
  --hud-c-aq: #3dc8ff;
  --hud-c-mix: #b46bff;
  --hud-bar-pattern: none;
}

/* 4-6, suit-cam visor: the frosted telemetry glass (the defaults above). */
.play[data-fidelity='4-6'] {
  --hud-font-display: 'Oxanium', sans-serif;
  --hud-font-body: 'Inter', sans-serif;
}

/* 2. The zone anchors (plan 16's grid, section 4). They carry no data attribute: their overlays do. */
.hud-zone {
  position: absolute;
  display: flex;
  flex-direction: column;
  gap: 8px;
  pointer-events: none;
  z-index: 20;
}
.hud-zone--top-left { top: 20px; left: clamp(16px, 2.5vw, 28px); max-width: min(300px, 40vw); align-items: flex-start; }
.hud-zone--top-centre { top: 20px; left: 0; right: 0; flex-direction: row; justify-content: center; align-items: center; gap: 12px; }
.hud-zone--top-right { top: 24px; right: 24px; align-items: flex-end; }
.hud-zone--bottom-left { left: 24px; bottom: 24px; align-items: flex-start; }
.hud-zone--bottom-right { right: 24px; bottom: 24px; align-items: flex-end; text-align: right; }

/* Overlays that the zones own take their place in the stack. */
.hud-zone .play-goal,
.hud-zone .play-sync,
.hud-zone .play-sync-indicator,
.hud-zone .play-plot,
.hud-zone .hm-beam-chip,
.hud-zone .radio-hud-btn {
  position: relative;
  left: auto;
  right: auto;
  top: auto;
  bottom: auto;
  transform: none;
  max-width: 100%;
}
.hud-zone .play-plot { width: 200px; }

/* 3. The compass ribbon (top-centre). */
.hud-compass {
  position: relative;
  width: min(300px, 46vw);
  height: 44px;
  padding: 6px 12px 4px;
  background: var(--hud-bg);
  backdrop-filter: var(--hud-backdrop);
  -webkit-backdrop-filter: var(--hud-backdrop);
  border: var(--hud-border);
  border-radius: var(--hud-radius);
  box-shadow: var(--hud-shadow);
  color: var(--hud-text);
  font-family: var(--hud-font-body);
  pointer-events: none;
}
.hud-compass-strip { position: relative; height: 18px; border-bottom: 1px solid rgba(255, 255, 255, 0.18); }
.hud-compass-tick { position: absolute; bottom: 0; width: 1px; height: 7px; background: var(--hud-text-dim); }
.hud-compass-tick.mid { height: 13px; background: var(--hud-text); }
.hud-compass-gate {
  position: absolute;
  top: 0;
  width: 0;
  height: 0;
  margin-left: -5px;
  border-left: 5px solid transparent;
  border-right: 5px solid transparent;
  border-top: 8px solid var(--hud-c-lx);
}
.hud-compass-gate.edge { border-top-color: var(--hud-c-pxd); }
/* TASK-26: the sync warning, at 30% outside a dome: the return arrow in amber, with a soft pulse */
.hud-compass-gate.warn { border-top-color: #ffc13d; filter: drop-shadow(0 0 4px #ffc13d); animation: hud-gate-warn 1.2s ease-in-out infinite; }
@keyframes hud-gate-warn { 50% { opacity: 0.45; } }
.hud-compass-label {
  display: block;
  margin-top: 2px;
  font-family: var(--hud-font-display);
  font-size: 11px;
  letter-spacing: 0.08em;
  text-align: center;
  color: var(--hud-text);
}
.hud-sync-word {
  font-family: var(--hud-font-display);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--hud-c-vtx);
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.8);
}
.hud-sync-word.draining { color: var(--hud-c-lx); }

/* 4. The four-float pill (top-right): one panel, the stage badge and four metric bars. */
.hud-floats {
  width: 232px;
  padding: 8px 12px 9px;
  background: var(--hud-bg);
  backdrop-filter: var(--hud-backdrop);
  -webkit-backdrop-filter: var(--hud-backdrop);
  border: var(--hud-border);
  border-radius: var(--hud-radius);
  box-shadow: var(--hud-shadow);
  color: var(--hud-text);
  font-family: var(--hud-font-body);
  pointer-events: none;
}
.hud-stage-badge {
  display: inline-block;
  margin-bottom: 6px;
  padding: 1px 8px;
  font-family: var(--hud-font-display);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: #050608;
  background: var(--hud-text);
  border-radius: var(--hud-radius);
}
.hud-floats-bars { display: grid; gap: 4px; margin: 0; padding: 0; list-style: none; }
.hud-floats-bars li { display: grid; grid-template-columns: 26px 1fr 26px; gap: 6px; align-items: center; font-size: 11px; }
.hud-float-name { font-family: var(--hud-font-display); color: var(--hud-text-dim); letter-spacing: 0.06em; }
.hud-float-bar { position: relative; display: block; height: 6px; overflow: hidden; background: rgba(255, 255, 255, 0.08); }
.hud-float-bar s { position: absolute; left: 0; top: 0; bottom: 0; background: var(--c, #ffffff); box-shadow: 0 0 8px var(--c, #ffffff); text-decoration: none; }
.hud-floats-bars li b { font-variant-numeric: tabular-nums; text-align: right; color: var(--hud-text); }
/* the bar's pattern, so the four still read apart in the low-bit skins */
.play[data-fidelity='0a'] .hud-float-bar { background: transparent; outline: 1px solid var(--c, #fff); }
.play[data-fidelity='0a'] .hud-float-bar s { background: transparent; box-shadow: none; border-right: 4px solid var(--c, #fff); }
.play[data-fidelity='0b'] .hud-float-bar s { background: var(--c, #fff); }
.play[data-fidelity='1'] .hud-float-bar s {
  background: repeating-linear-gradient(90deg, var(--c, #fff) 0 calc(12.5% - 2px), transparent calc(12.5% - 2px) 12.5%);
  box-shadow: none;
}
.play[data-fidelity='2'] .hud-float-bar { background: #0c111a; box-shadow: inset 1px 1px 0 #000; }
.play[data-fidelity='2'] .hud-float-bar s { box-shadow: inset 0 -2px 0 rgba(255, 255, 255, 0.45); }
.play[data-fidelity='3'] .hud-float-bar s,
.play[data-fidelity='4-6'] .hud-float-bar s {
  background: linear-gradient(90deg, color-mix(in srgb, var(--c, #fff) 60%, transparent), var(--c, #fff));
}

/* 5. The machine label (aim or Alt only) and the aim-gated machine state. */
.hud-machine-label {
  position: absolute;
  transform: translate(-50%, -100%);
  display: grid;
  justify-items: center;
  gap: 2px;
  padding: 4px 10px;
  background: var(--hud-bg);
  border: var(--hud-border);
  border-radius: var(--hud-radius);
  color: var(--hud-text);
  font-family: var(--hud-font-body);
  white-space: nowrap;
  pointer-events: none;
  z-index: 24;
}
.hud-machine-label b { font-family: var(--hud-font-display); font-size: 12px; letter-spacing: 0.06em; }
.hud-machine-label span { font-size: 11px; color: var(--hud-text-dim); }
.hud-machine-label.tone-ok span { color: var(--hud-c-vtx); }
.hud-machine-label.tone-warn span { color: var(--hud-c-lx); }
.hud-machine-label.tone-bad span { color: var(--hud-c-pxd); }

/* 6. The skin shift: 120 ms of glitch on the zones, never on the subtitle (it does not break a sentence). */
@keyframes hud-fidelity-shift {
  0%   { transform: translateX(-3px); filter: contrast(1.6) brightness(1.3); clip-path: inset(0 0 40% 0); }
  40%  { transform: translateX(3px); filter: hue-rotate(40deg) contrast(1.2); clip-path: inset(30% 0 0 0); }
  80%  { transform: translateX(-1px); filter: brightness(1.15); clip-path: inset(0 0 0 0); }
  100% { transform: none; filter: none; clip-path: none; }
}
.play.hud-glitch .hud-zone { animation: hud-fidelity-shift 120ms steps(3, end) 1; }
.play.hud-glitch .mentor-subtitle { animation: none; }
@media (prefers-reduced-motion: reduce) {
  .play.hud-glitch .hud-zone { animation: none; }
}

/* 7. Clean shots (?cleanShot=1) drop the pointer-lock prompt, as before. */
body.clean-shot [data-pointer-lock-prompt] { display: none !important; }

/* 8. The overlays that keep their own JSX but take a zone by coordinates (TASK-25). */
/* the prompt and CANNOT PLACE sit 36 px under the reticle, outside its 48 px clear zone */
.play .play-prompt { top: calc(50% + 36px); }
/* the Moon-arrival build hint and the plan prompt share the centre */
.play .hm-plan-build-prompt { white-space: nowrap; }
/* the beam tool chip: the bottom-right stack, above the resource ticker */
.play .hm-beam-chip { position: absolute; right: 24px; bottom: 124px; max-width: 200px; }
/* pickup counters: bottom-right, above the tool; the placed counter one line higher */
/* the pickup counters stack in the bottom-left, above the weapon badge: 62 px each, clear of the health panel (bottom-right) */
.play .hm-harvest-counter { left: 24px; right: auto; bottom: 200px; }
.play .hm-harvest-counter[data-testid='base-placed-counter'] { bottom: 300px; }
/* the active plans card: under the top-right stack */
.play .hm-plans-hud-card { top: 236px; right: 24px; }

/* 9. The build ribbon (B): a bottom-docked drawer, 136 px tall, at most 820 px wide. Its width is capped so it never
 *    reaches the bottom-left and bottom-right stacks (200 px each, 24 px in): min(820px, 100vw - 496px). */
.play .play-build.bm-ribbon {
  left: 50%;
  right: auto;
  top: auto;
  bottom: 104px;
  transform: translateX(-50%);
  width: min(820px, calc(100vw - 496px));
  max-width: 820px;
  height: 136px;
  max-height: 136px;
  padding: 8px 12px 6px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  overflow: hidden;
  background: var(--hud-bg);
  backdrop-filter: var(--hud-backdrop);
  -webkit-backdrop-filter: var(--hud-backdrop);
  border: var(--hud-border);
  border-radius: var(--hud-radius);
  box-shadow: var(--hud-shadow);
  color: var(--hud-text);
  font-family: var(--hud-font-body);
  pointer-events: auto;
  z-index: 30;
}
.play .bm-ribbon .bm-tabs-row { display: flex; align-items: stretch; gap: 8px; }
.play .bm-ribbon .bm-tabs-row .bm-tabs { flex: 1; }
.play .bm-ribbon .bm-close { align-self: center; }
.play .bm-ribbon .bm-panel { min-height: 0; flex: 1; overflow: hidden; }
.play .bm-ribbon .play-cards { display: flex; gap: 8px; overflow-x: auto; padding-bottom: 2px; }
.play .bm-ribbon .play-card { min-width: 150px; flex: 0 0 auto; padding: 6px 10px; }
.play .bm-ribbon .play-card b { font-size: 14px; }
.play .bm-ribbon .play-card span { font-size: 11px; }
.play .bm-ribbon .play-card em { font-size: 11px; }
.play .bm-ribbon .bm-group { display: inline-block; margin-right: 12px; }
.play .bm-ribbon .bm-chips { display: flex; gap: 6px; overflow-x: auto; }
.play .bm-ribbon p { display: none; }
.play .bm-keys {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 14px;
  font-family: var(--hud-font-body);
  font-size: 11px;
  color: var(--hud-text-dim);
}
.play .bm-keys kbd, .play .bm-pill kbd {
  display: inline-block;
  min-width: 16px;
  padding: 0 4px;
  font-family: var(--hud-font-display);
  font-size: 10px;
  color: var(--hud-text);
  border: 1px solid var(--hud-text-dim);
  border-radius: var(--hud-radius);
}

/* 10. The collapsed build pill (the drawer once a card is picked): a small header, bottom-centre, above the hotbar. */
.play .bm-pill.play-build {
  left: 50%;
  top: auto;
  right: auto;
  bottom: 104px;
  transform: translateX(-50%);
  width: max-content;
  max-width: calc(100vw - 496px);
  height: auto;
  max-height: none;
  padding: 4px 12px;
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--hud-bg);
  backdrop-filter: var(--hud-backdrop);
  -webkit-backdrop-filter: var(--hud-backdrop);
  border: var(--hud-border);
  border-radius: var(--hud-radius);
  box-shadow: var(--hud-shadow);
  color: var(--hud-text);
  font-family: var(--hud-font-body);
  font-size: 11px;
  overflow: visible;
  pointer-events: auto;
  z-index: 30;
}
.play .bm-pill-open {
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding: 0;
  background: none;
  border: 0;
  color: var(--hud-text);
  cursor: pointer;
  white-space: nowrap;
}
.play .bm-pill-open b { font-family: var(--hud-font-display); font-size: 12px; letter-spacing: 0.06em; color: var(--tab, var(--hud-c-lx)); }
.play .bm-pill-open span { color: var(--hud-text-dim); }
.play .bm-pill-keys { color: var(--hud-text-dim); white-space: nowrap; }

/* 11. The monster panels (TASK-25): the radar top-right under the comms, the health panel above the beam chip (clear of
 *     the subtitle and the drawer), the seal plate in the centre below the reticle's clear zone. */
.play .mhud-radar { top: 224px; right: 24px; width: 232px; }
.play .mhud-vitals { right: 24px; bottom: 200px; width: 200px; }
/* the drawer shows a card's name and cost only (136 px is tight); its blurb stays in the full menu */
.play .bm-ribbon .play-card span { display: none; }
.play .bm-ribbon .bm-tab { padding: 4px 10px; }
.play .bm-ribbon .play-card em { display: block; margin-top: 2px; }
/* the title card keeps to 600 px, so its left edge clears the quest panel (28-328 px) on the arrival shots */
.play .play-toast { max-width: 600px; }
/* while a radio line is up, the build readout drops its wheel and rotation hints (the readout ends above the subtitle band) */
body[data-subtitle-up] .play .hm-build-wheel-hint,
body[data-subtitle-up] .play .hm-build-rot-hint { display: none; }
/* the build readout holds for a title card, as CANNOT PLACE does (body[data-title-up], set by every toast for 3 s) */
body[data-title-up] .play .hm-build-readout-hud { display: none; }

