/* ============================================================================
 * File: apps/web/src/base/ui/radial-menu.css
 * TICKET-04 (OPUS_NOTE_11 Item C):
 * Dark-glass telemetry styling for RadialMenu using the HUD vocabulary
 * (--hud-bg, --hud-border, --hud-font-display Oxanium, --hud-font-body Inter).
 * ============================================================================ */

.hm-radial-overlay {
  position: fixed;
  inset: 0;
  z-index: 120;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(4, 8, 16, 0.42);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  user-select: none;
  pointer-events: auto;
}

.hm-radial-wheel {
  position: relative;
  width: 380px;
  height: 380px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.hm-radial-svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
}

.hm-radial-outer-ring {
  fill: rgba(8, 13, 22, 0.58);
  stroke: rgba(255, 255, 255, 0.14);
  stroke-width: 1.25;
}

.hm-radial-wedge {
  fill: var(--hud-bg, rgba(10, 15, 24, 0.78));
  stroke: rgba(255, 255, 255, 0.16);
  stroke-width: 1.2;
  cursor: pointer;
  transition: fill 0.1s ease, stroke 0.1s ease, filter 0.1s ease;
}

.hm-radial-wedge.is-active {
  fill: rgba(61, 200, 255, 0.22);
  stroke: var(--hud-c-aq, #3dc8ff);
  stroke-width: 2;
  filter: drop-shadow(0 0 12px rgba(61, 200, 255, 0.35));
}

.hm-radial-wedge.is-locked {
  fill: rgba(15, 19, 28, 0.55);
  stroke: rgba(255, 61, 138, 0.25);
  cursor: not-allowed;
}

.hm-radial-wedge.is-locked.is-active {
  fill: rgba(255, 61, 138, 0.16);
  stroke: var(--hud-c-pxd, #ff3d8a);
  filter: drop-shadow(0 0 10px rgba(255, 61, 138, 0.3));
}

.hm-radial-slice {
  position: absolute;
  transform: translate(-50%, -50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  width: 82px;
  padding: 4px;
  background: none;
  border: none;
  color: var(--hud-text, #f4f8ff);
  font-family: var(--hud-font-body, 'Inter', sans-serif);
  cursor: pointer;
  pointer-events: auto;
  text-align: center;
}

.hm-radial-slice.is-locked {
  opacity: 0.52;
  cursor: not-allowed;
}

.hm-radial-slice-thumb {
  width: 40px;
  height: 40px;
  object-fit: contain;
  border-radius: 6px;
  background: rgba(4, 8, 15, 0.55);
  border: 1px solid rgba(255, 255, 255, 0.14);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.45);
}

.hm-radial-slice.is-active .hm-radial-slice-thumb {
  border-color: var(--hud-c-aq, #3dc8ff);
  box-shadow: 0 0 10px rgba(61, 200, 255, 0.4);
}

.hm-radial-slice-dot {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--hud-c-aq, #3dc8ff);
  box-shadow: 0 0 8px var(--hud-c-aq, #3dc8ff);
}

.hm-radial-slice-label {
  font-family: var(--hud-font-display, 'Oxanium', sans-serif);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.04em;
  line-height: 1.15;
  color: var(--hud-text, #f4f8ff);
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.9);
  max-width: 80px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.hm-radial-slice-lock-tag {
  font-family: var(--hud-font-display, 'Oxanium', sans-serif);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.08em;
  padding: 1px 4px;
  border-radius: 3px;
  color: #fda4af;
  background: rgba(255, 61, 138, 0.22);
  border: 1px solid rgba(255, 61, 138, 0.4);
}

.hm-radial-hub {
  position: relative;
  z-index: 2;
  width: 116px;
  height: 116px;
  border-radius: 50%;
  padding: 10px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  text-align: center;
  background: var(--hud-bg, rgba(10, 15, 24, 0.92));
  border: 1px solid rgba(255, 255, 255, 0.22);
  box-shadow: var(--hud-shadow, 0 8px 28px rgba(0, 0, 0, 0.65));
  pointer-events: none;
}

.hm-radial-hub-hint {
  font-family: var(--hud-font-display, 'Oxanium', sans-serif);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--hud-c-aq, #3dc8ff);
}

.hm-radial-hub-title {
  font-family: var(--hud-font-display, 'Oxanium', sans-serif);
  font-size: 12px;
  font-weight: 700;
  line-height: 1.2;
  color: var(--hud-text, #f4f8ff);
}

.hm-radial-hub-locked {
  font-family: var(--hud-font-body, 'Inter', sans-serif);
  font-size: 10px;
  line-height: 1.2;
  color: var(--hud-c-pxd, #ff3d8a);
}

.hm-radial-hub-keys {
  font-family: var(--hud-font-body, 'Inter', sans-serif);
  font-size: 9px;
  line-height: 1.25;
  color: var(--hud-text-dim, #94a3b8);
}

.hm-radial-hub-keys kbd {
  display: inline-block;
  padding: 0 3px;
  font-family: var(--hud-font-display, 'Oxanium', sans-serif);
  font-size: 9px;
  color: var(--hud-text, #f4f8ff);
  border: 1px solid rgba(255, 255, 255, 0.25);
  border-radius: 3px;
}

